  VALUES (v_section_id, v_module_id, $ob$The Biology of Stress$ob$, $ob$the-biology-of-stress$ob$, 1, NULL);
  -- p0 [level-1 header] Stress response systems: The body's coordinated defense
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Stress response systems: The body's coordinated defense"}]}$ob$::jsonb, $ob$Stress response systems: The body's coordinated defense$ob$, 0, false, NULL, NULL, true, 1);
  -- p1 [text L1] When faced with a stressor, the body activates a network of brain and peripheral systems designed
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"When faced with a stressor, the body activates a network of brain and peripheral systems designed to ensure survival (Cannon, 1929; Selye, 1936; Chrousos and Gold, 1992; McEwen, 2007). A primary consequence of this activation is the mobilization of energy sources, enabling the body to respond effectively to immediate and sustained challenges (Munck et al., 1984; Sapolsky et al., 2000; Charmandari et al., 2005). At the core of this response are the <strong>sympathetic nervous system (SNS)</strong> and the <strong>hypothalamus-pituitary-adrenal (HPA) axis (Figure 2)</strong>, two complementary systems with distinct but interconnected roles (Charmandari et al., 2005; Ulrich-Lai and Herman, 2009; Russell and Lightman, 2019). The SNS is activated almost instantly, comprising both organ-specific sympathetic neural outflow and the sympathoadrenomedullary endocrine response, and triggering the classic <em>fight-or-flight</em> response, characterized by rapid physiological changes, such as increased heart rate, energy mobilization, and the redistribution of blood flow to muscles (Cannon, 1929; Goldstein, 2010; Wehrwein et al., 2016). In contrast, the HPA axis begins to respond within minutes, releasing glucocorticoid hormones (primarily cortisol in humans and corticosterone in rodents) into the bloodstream over a slower time course, where they reach numerous targets to sustain the stress response, regulate energy balance, and support adaptation to prolonged stressors and recovery (Joëls and Baram, 2009; Russell and Lightman, 2019)."}]}$ob$::jsonb, $ob$When faced with a stressor, the body activates a network of brain and peripheral systems designed to ensure survival (Cannon, 1929; Selye, 1936; Chrousos and Gold, 1992; McEwen, 2007). A primary…$ob$, 1, false, NULL, NULL, false, 1);
  -- p2 [figure 2] Figure 2. The two stress response systems: the sympathetic nervous system and the HPA axis.
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":2,"caption":"The two stress response systems: the sympathetic nervous system and the HPA axis."},{"type":"text","content":". The two stress response systems: the sympathetic nervous system and the HPA axis."}]}$ob$::jsonb, $ob$Figure 2. The two stress response systems: the sympathetic nervous system and the HPA axis.$ob$, 2, true, v_fig_2, 'auto', false, 1);
  -- p3 [text L1] While distinct, these systems work in conjunction, with the SNS often “priming” the body for imme
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"While distinct, these systems work in conjunction, with the SNS often “priming” the body for immediate survival needs and the HPA axis contributing to longer-term adaptations (Chrousos and Gold, 1992). They should not, however, be understood as a rigid two-stage sequence; rather, their relative recruitment, magnitude, and temporal dynamics vary according to the nature, intensity, duration, predictability, and controllability of the stressor, as well as the organism’s appraisal and physiological state (Kvetnansky et al., 2009; Carter and Goldstein, 2015; Agorastos and Chrousos, 2022). Sympathetic neural output and circulating catecholamines prepare the organism for immediate demands, whereas glucocorticoids exert a myriad of effects, ranging from permissive, to either stimulatory or suppressive, that facilitate adaptation not only during but also after the challenge (Munck et al., 1984; Sapolsky et al., 2000; Charmandari et al., 2005)."}]}$ob$::jsonb, $ob$While distinct, these systems work in conjunction, with the SNS often “priming” the body for immediate survival needs and the HPA axis contributing to longer-term adaptations (Chrousos and Gold,…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [level-2 header] The sympathetic nervous system (SNS): The rapid responder
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":4,"content":"The sympathetic nervous system (SNS): The rapid responder"}]}$ob$::jsonb, $ob$The sympathetic nervous system (SNS): The rapid responder$ob$, 4, false, NULL, NULL, true, 2);
  -- p5 [text L2] Imagine walking alone at dusk, enjoying the quiet, when a sudden sound from the shadows triggers 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Imagine walking alone at dusk, enjoying the quiet, when a sudden sound from the shadows triggers an immediate reaction. Your heart races, breathing speeds up, and your senses sharpen. This rapid response exemplifies the response of the sympathetic nervous system (SNS), the body’s natural alarm system, which triggers swift physiological adjustments to confront or escape potential threats (Cannon, 1929; Goldstein, 2010). Acting as part of the autonomic nervous system (ANS), the SNS integrates signals from the brain and body to initiate immediate responses critical for survival (Wehrwein et al., 2016; Kvetnansky et al., 2009)"}]}$ob$::jsonb, $ob$Imagine walking alone at dusk, enjoying the quiet, when a sudden sound from the shadows triggers an immediate reaction. Your heart races, breathing speeds up, and your senses sharpen. This rapid…$ob$, 5, false, NULL, NULL, false, 2);
  -- p6 [text L2] Sympathetic output is organized by a distributed central autonomic network (Figure 3). Cortical a
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Sympathetic output is organized by a distributed central autonomic network (Figure 3). Cortical and limbic structures [such as the insular cortex (IC), anterior cingulate cortex (ACC) and amygdala (A)] process sensory appraisal and emotional context, while the locus coeruleus (LC) promotes central arousal and vigilance. Hypothalamic areas, particularly the paraventricular nucleus (PVN), integrate stress-related signals from the brain and body to engage downstream premotor pathways in the rostral ventrolateral medulla (RVLM). These signals then descend through the spinal cord to the intermediolateral column (IML) of the thoracic and upper lumbar cord (Dampney, 2016; Ulrich-Lai and Herman, 2009), where preganglionic neurons relay these signals through two distinct organizational systems, a direct neural (sympathoneural) pathway and a hormonal (sympathoadrenal) one."}]}$ob$::jsonb, $ob$Sympathetic output is organized by a distributed central autonomic network (Figure 3). Cortical and limbic structures [such as the insular cortex (IC), anterior cingulate cortex (ACC) and amygdala…$ob$, 6, false, NULL, NULL, false, 2);
