  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":3,"caption":"The sympathetic nervous system's central autonomic network (interactive)."},{"type":"text","content":". The sympathetic nervous system's central autonomic network (interactive)."}]}$ob$::jsonb, $ob$Figure 3. The sympathetic nervous system's central autonomic network (interactive).$ob$, 7, true, v_fig_3, 'auto', false, 2);
  -- p8 [text L2] The sympathoneural pathway comprises projections of preganglionic neurons in the IML to sympathet
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The sympathoneural pathway comprises projections of preganglionic neurons in the IML to sympathetic ganglia, where they release acetylcholine (ACh) that acts on nicotinic receptors, activating postganglionic neurons, which most release norepinephrine (NE) as their primary neurotransmitter onto α and β adrenergic receptors in target organs to regulate cardiovascular, respiratory, metabolic, renal, and gastrointestinal functions. An important exception is the sympathetic innervation of most eccrine sweat glands, where postganglionic terminals release ACh instead of NE. This direct neural arrangement ensures rapid, highly localized, and tissue-specific communication with peripheral targets."}]}$ob$::jsonb, $ob$The sympathoneural pathway comprises projections of preganglionic neurons in the IML to sympathetic ganglia, where they release acetylcholine (ACh) that acts on nicotinic receptors, activating…$ob$, 8, false, NULL, NULL, false, 2);
  -- p9 [text L2] The sympathoadrenal system, typically activated simultaneously, involves the innervation of prega
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The sympathoadrenal system, typically activated simultaneously, involves the innervation of preganglionic sympathetic fibers directly to innervate chromaffin cells in the adrenal medulla (the central part of the adrenal gland) where ACh release triggers the systemic release of catecholamines [adrenaline or epinephrine (E), along with smaller amounts of NE] directly into the bloodstream (Goldstein, 2010; Carter and Goldstein, 2015). Acting on adrenergic receptors distributed throughout the body, these catecholamines trigger widespread physiological changes that support the body’s response to stress. This hormonal component extends both the spatial reach and duration of the sympathetic response, ensuring a coordinated regulation of target organs and metabolic tissues that lack the direct sympathetic innervation pathway. It should be noted, though, that given that both pathways can be engaged independently depending on the stressor, circulating adrenaline should not be viewed as a universal proxy for overall sympathetic neural activity (Kvetnansky et al., 2009; Carter and Goldstein, 2015)."}]}$ob$::jsonb, $ob$The sympathoadrenal system, typically activated simultaneously, involves the innervation of preganglionic sympathetic fibers directly to innervate chromaffin cells in the adrenal medulla (the…$ob$, 9, false, NULL, NULL, false, 2);
  -- p10 [text L2] The SNS exerts its effects by activating physiological systems critical for immediate survival w
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The SNS exerts its effects by activating physiological systems critical for immediate survival while simultaneously inhibiting non-essential functions during acute stress, temporarily downregulating the non-survival critical processes to direct energy where it is most needed."}]}$ob$::jsonb, $ob$The SNS exerts its effects by activating physiological systems critical for immediate survival while simultaneously inhibiting non-essential functions during acute stress, temporarily downregulating…$ob$, 10, false, NULL, NULL, false, 2);
  -- p11 [text L2] Systems activated by the SNS during acute stress
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Systems activated by the SNS during acute stress</strong>"}]}$ob$::jsonb, $ob$Systems activated by the SNS during acute stress$ob$, 11, false, NULL, NULL, false, 2);
  -- p12 [text L2] Cardiovascular system: The SNS increases cardiac output by augmenting both stroke volume and hea
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Cardiovascular system:</strong> The SNS increases cardiac output by augmenting both stroke volume and heart rate, aligning cardiovascular performance with the body’s metabolic demands during stress or activity (Guyenet, 2006; Wehrwein et al., 2016). Specifically, it increases heart rate and myocardial contractility, predominantly via β1-adrenergic receptors. At the same time, it redistributes blood flow from visceral compartments, such as the gastrointestinal tract, kidneys and skin, principally through α1-adrenergic receptors for vasoconstriction (Guimaraes and Moura, 2001). Blood flow to activate skeletal muscle is maintained and enhanced through an interplay between local metabolic vasodilation, sympathetic neural vasoconstriction tone, and β2-adrenergic vasodilation mediated by circulating adrenaline (Guyenet, 2006), ensuring optimal oxygen and nutrient delivery to active tissues."}]}$ob$::jsonb, $ob$Cardiovascular system: The SNS increases cardiac output by augmenting both stroke volume and heart rate, aligning cardiovascular performance with the body’s metabolic demands during stress or…$ob$, 12, false, NULL, NULL, false, 2);
  -- p13 [text L2] Respiratory system: Sympathetic activation promotes bronchodilation predominantly through the ac
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Respiratory system:</strong> Sympathetic activation promotes bronchodilation predominantly through the action of circulating adrenaline acting on β2-adrenergic receptors located on airway smooth muscle (Barnes, 1993; Wehrwein et al., 2016) to expand airways, enhancing oxygen intake and facilitating carbon dioxide removal, thereby ensuring adequate respiratory support for heightened physical and metabolic demands during stress."}]}$ob$::jsonb, $ob$Respiratory system: Sympathetic activation promotes bronchodilation predominantly through the action of circulating adrenaline acting on β2-adrenergic receptors located on airway smooth muscle…$ob$, 13, false, NULL, NULL, false, 2);
  -- p14 [text L2] Metabolism: The sympathoadrenal pathway mobilizes energy reserves by stimulating hepatic glycoge
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Metabolism:</strong> The sympathoadrenal pathway mobilizes energy reserves by stimulating hepatic glycogenolysis and adipose tissue lipolysis (via β2- and β3-adrenergic receptors), ensuring a steady supply of glucose, glycerol, and free fatty acids to fuel muscles and other energy-demanding tissues (Nonogaki, 2000; Kvetnansky et al., 2009). Crucially, sympathetic signaling also inhibits pancreatic insulin release (predominantly via α2-adrenergic receptors on beta cells) while stimulating glucagon secretion from alpha cells (via β2-adrenergic receptors) involving both sympathetic signaling branches (Porte and Robertson, 1973; Nonogaki, 2000). These coordinated hormonal and neural actions prevent glucose uptake by storage tissues, prioritizing the immediate availability of glucose and fatty acids as fuel for active tissues, such as the brain, heart and active skeletal muscles, where they are most needed."}]}$ob$::jsonb, $ob$Metabolism: The sympathoadrenal pathway mobilizes energy reserves by stimulating hepatic glycogenolysis and adipose tissue lipolysis (via β2- and β3-adrenergic receptors), ensuring a steady supply…$ob$, 14, false, NULL, NULL, false, 2);
  -- p15 [text L2] Immune system: Through the release of adrenaline and noradrenaline and their binding to adrenerg
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Immune system:</strong> Through the release of adrenaline and noradrenaline and their binding to adrenergic receptors (primarily β2) on leukocytes and lymphoid organs, the activation of the SNS leads to rapid mobilization of immune cells (Elenkov et al., 2000; Dhabhar et al., 2012). Citotoxic lymphocytes, including natural killer (NK) cells and effector T cells, are swiftly mobilized from marginal pools into the bloodstream, followed by the trafficking of neutrophils, and monocytes toward barrier organs like the skin. Through these responses, the immune system’s deployment of elements into the circulation during stress responses is designed to enhance immune surveillance and, thus, the body’s capacity to prepare frontline tissues to detect and respond to potential injuries or infections. However, it should not be considered as a uniform enhancement of immunity, as acute stress changes where different immune cell populations are located and how they function, and these effects vary with cell type, stressor intensity, and the accompanying glucocorticoid response (Dhabhar et al., 2012)."}]}$ob$::jsonb, $ob$Immune system: Through the release of adrenaline and noradrenaline and their binding to adrenergic receptors (primarily β2) on leukocytes and lymphoid organs, the activation of the SNS leads to…$ob$, 15, false, NULL, NULL, false, 2);
  -- p16 [text L2] Vision: The SNS enhances visual processing by increasing pupil dilation (mydriasis) through the 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Vision:</strong> The SNS enhances visual processing by increasing pupil dilation (mydriasis) through the contraction of the pupillary dilator via α1-adrenergic receptors (McDougal and Gamlin, 2015). By allowing more light to enter the eye, mydriasis increases retina illumination and enhances peripheral visual sensitivity, optimizing fine focal visual acuity in low-light or high-alert situations. This response supports heightened visual sensitivity and adaptability during stress or arousal, improving the ability to detect potential threats (Bradley et al., 2008)."}]}$ob$::jsonb, $ob$Vision: The SNS enhances visual processing by increasing pupil dilation (mydriasis) through the contraction of the pupillary dilator via α1-adrenergic receptors (McDougal and Gamlin, 2015). By…$ob$, 16, false, NULL, NULL, false, 2);
  -- p17 [text L2] Systems generally deprioritized by the SNS during acute stress
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Systems generally deprioritized by the SNS during acute stress</strong>"}]}$ob$::jsonb, $ob$Systems generally deprioritized by the SNS during acute stress$ob$, 17, false, NULL, NULL, false, 2);
  -- p18 [text L2] Digestive system: The activated SNS generally suppresses digestive activity during acute stress,
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Digestive system:</strong> The activated SNS generally suppresses digestive activity during acute stress, thereby reducing the immediate energetic investment in good processing and, thus, conserving energy for critical survival functions. Specifically, it reduces gastrointestinal motility and secretions through direct effects on the enteric nervous system and through interactions with parasympathetic transmission (Browning and Travagli, 2014; Furness, 2012). Presynaptic α2-adrenergic receptors inhibit ACh release from enteric and parasympathetic terminals, while β2-adrenergic signaling promotes relaxation of the gastrointestinal wall. Concurrently, α1-adrenergic stimulation mediates sphincter contraction and splanchnic vasoconstriction, redirecting blood flow away from the gut to activate skeletal muscle in a manner graded by stressor intensity (Furness, 2012)."}]}$ob$::jsonb, $ob$Digestive system: The activated SNS generally suppresses digestive activity during acute stress, thereby reducing the immediate energetic investment in good processing and, thus, conserving energy…$ob$, 18, false, NULL, NULL, false, 2);
  -- p19 [text L2] Renal system: During acute stressors or homeostatic threat, intense sympathetic activation const
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Renal system:</strong> During acute stressors or homeostatic threat, intense sympathetic activation constricts the renal vasculature via α1-adrenergic receptors, modulating renal blood flow and glomerular filtration (DiBona and Kopp, 1997; Johns et al., 2011). The SNS coordinates renal mechanisms to preserve circulating blood volume and arterial pressure, suppressing non-essential kidney functions and prioritizing cardiovascular stability and fluid conservation by stimulating renin release from the kidneys (via β1-adrenergic receptors), and thus activating the renin-angiotensin-aldosterone system (RAAS) to increase blood pressure and promote sodium and water retention. Moreover, direct renal sympathetic nerve activity enhances tubular sodium reabsorption, further regulating systemic hemodynamics during acute stressful challenges (DiBona and Kopp, 1997; Johns et al., 2011)."}]}$ob$::jsonb, $ob$Renal system: During acute stressors or homeostatic threat, intense sympathetic activation constricts the renal vasculature via α1-adrenergic receptors, modulating renal blood flow and glomerular…$ob$, 19, false, NULL, NULL, false, 2);
  -- p20 [text L2] Reproductive system: During acute stress, the SNS suppresses non-urgent reproductive processes, 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Reproductive system:</strong> During acute stress, the SNS suppresses non-urgent reproductive processes, primarily by reducing genital blood flow via α1-adrenergic vasoconstriction and dampening parasympathetic tone required for initial physiological arousal, penile and clitoral vasodilation, and vaginal lubrication (Meston, 2000). This dual action helps conserve energy and resources during acute stress, which, if prolonged, can lead to deeper reproductive suppression through direct inhibition of the hypothalamic-pituitary-gonadal (HPG) axis and associated health outcomes (Rivier and Rivest, 1991; Wingfield and Sapolsky, 2003)."}]}$ob$::jsonb, $ob$Reproductive system: During acute stress, the SNS suppresses non-urgent reproductive processes, primarily by reducing genital blood flow via α1-adrenergic vasoconstriction and dampening…$ob$, 20, false, NULL, NULL, false, 2);
  -- p21 [level-2 header] The HPA axis: Sustained regulation during stress
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":4,"content":"The HPA axis: Sustained regulation during stress"}]}$ob$::jsonb, $ob$The HPA axis: Sustained regulation during stress$ob$, 21, false, NULL, NULL, true, 2);
  -- p22 [text L2] The hypothalamus-pituitary-adrenal (HPA) axis provides a sustained, regulatory mechanism that fa
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The hypothalamus-pituitary-adrenal (HPA) axis provides a sustained, regulatory mechanism that facilitates adaptation, energy reallocation, and recovery during and after challenges. Although it operates on a slower timescale than the direct sympathetic neurotransmission, the HPA axis is an integral component of the acute cascade (Joëls and Baram, 2009; Russell and Lightman, 2019). Its final product involves the synthesis and release of glucocorticoid (GC) hormones that act on nearly every organ to regulate a wide range of general and cell-specific functions. Its activation is critical for mobilizing energy reserves and modulating physiological functions, including cardiovascular tone, metabolic homeostasis, and immune activity, as well as cognitive, emotional, and behavioral responses (Charmandari et al., 2005; Herman et al., 2016). However, while the HPA axis is essential for survival during acute stress, its prolonged or dysregulated activity can lead to maladaptive outcomes, allostatic load and stress-related pathologies (McEwen , 1998; McEwen and Wingfield, 2003). Importantly, HPA axis dysregulation is not limited to GC hypersecretion; it can also manifest as blunted responsiveness, delayed post-stress termination, tissue-specific glucocorticoid resistance, or disruptions in baseline circadian and ultradian pulsatility (Russell and Lightman, 2019; Agorastos and Chrousos, 2022)."}]}$ob$::jsonb, $ob$The hypothalamus-pituitary-adrenal (HPA) axis provides a sustained, regulatory mechanism that facilitates adaptation, energy reallocation, and recovery during and after challenges. Although it…$ob$, 22, false, NULL, NULL, false, 2);
  -- p23 [text L2] The key components of this neuroendocrine system include the hypothalamus, the anterior pituitar
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The key components of this neuroendocrine system include the hypothalamus, the anterior pituitary gland, and the adrenal cortex, each playing a distinct yet interconnected role in the stress response. Communication between these components is sequentially regulated by molecular signals originating from both neuronal systems in the brain [e.g., corticotropin releasing hormone (CRH) and arginine vasopressin (AVP) from the hypothalamus] and endocrine glands [adrenocorticotropic hormone (ACTH) from the pituitary and glucocorticoids from the adrenal cortex], embedded (Ulrich-Lai and Herman, 2009)."}]}$ob$::jsonb, $ob$The key components of this neuroendocrine system include the hypothalamus, the anterior pituitary gland, and the adrenal cortex, each playing a distinct yet interconnected role in the stress…$ob$, 23, false, NULL, NULL, false, 2);
  -- p24 [text L2] Hypothalamus: The HPA axis originates in the parvocellular neurosecretory neurons of the paraven
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Hypothalamus:</strong> The HPA axis originates in the parvocellular neurosecretory neurons of the paraventricular nucleus (PVN) of the hypothalamus (specifically its medial parvocellular division), which integrates stress-related inputs from limbic, cortical, and brainstem pathways (Ulrich-Lai and Herman, 2009; Herman et al., 2016). These neurons project to the capillaries of the median eminence, where they release CRH and AVP into the pituitary portal circulation (Vale et al., 1981). From there, CRH binds to corticotropin-releasing hormone receptors type 1 (CRHR1) on anterior pituitary corticotrophs, driving the synthesis and release of ACTH. AVP acts synergistically through vasopressin V1b receptors (V1bRs) to amplify CRH-mediated ACTH secretion, a mechanism that becomes particularly prominent in maintaining HPA activation during repeated, intense or prolonged stress (Gillies et al., 1982; Herman et al., 2016)."}]}$ob$::jsonb, $ob$Hypothalamus: The HPA axis originates in the parvocellular neurosecretory neurons of the paraventricular nucleus (PVN) of the hypothalamus (specifically its medial parvocellular division), which…$ob$, 24, false, NULL, NULL, false, 2);
  -- p25 [text L2] Pituitary gland: Upon stimulation by CRH and/ AVP, anterior pituitary corticotrophs cleave the p
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Pituitary gland:</strong> Upon stimulation by CRH and/ AVP, anterior pituitary corticotrophs cleave the precursor pro-opiomelanocortin (POMC) to release ACTH into the systemic circulation. ACTH acts as the primary circulating messenger to the adrenal cortex, where it binds to melanocortin type 2 receptors (Mc2R) on adrenocortical cells (Gallo-Payet, 2016), stimulating the production and secretion of glucocorticoids in the adrenal glands."}]}$ob$::jsonb, $ob$Pituitary gland: Upon stimulation by CRH and/ AVP, anterior pituitary corticotrophs cleave the precursor pro-opiomelanocortin (POMC) to release ACTH into the systemic circulation. ACTH acts as the…$ob$, 25, false, NULL, NULL, false, 2);
  -- p26 [text L2] Adrenal cortex: The final component of the HPA axis is the adrenal cortex, which forms the outer
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Adrenal cortex:</strong> The final component of the HPA axis is the adrenal cortex, which forms the outer layer of the adrenal glands. Upon stimulation by ACTH, cells in the <em>zona fasciculata</em> synthesize and secrete glucocorticoid hormones; primarily cortisol in humans and corticosterone in rodents, which mediate the sustained physiological response to stress (Miller and Auchus, 2011). Glucocorticoids are lipophilic hormones and, thus, not pre-stored in vesicles, but synthesized de novo from cholesterol on demand. The <em>zona reticularis</em>, also responsive to ACTH, produces small amounts of adrenal androgens, principally dehydroepiandrosterone (DHEA) and its sulfate ester (DHEAS) in primates, which may modulate stress-related processes."}]}$ob$::jsonb, $ob$Adrenal cortex: The final component of the HPA axis is the adrenal cortex, which forms the outer layer of the adrenal glands. Upon stimulation by ACTH, cells in the zona fasciculata synthesize and…$ob$, 26, false, NULL, NULL, false, 2);
  -- p27 [text L2] Glucocorticoid receptors and mechanisms of action: GCs act primarily through two intracellular a
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Glucocorticoid receptors and mechanisms of action:</strong> GCs act primarily through two intracellular and membrane receptor types, the mineralocorticoid receptor (MR) and the glucocorticoid receptor (GR). While GR is ubiquitously expressed across peripheral tissues and the central nervous system, MR shows a more restricted distribution, with high expression in limbic structures, such as the hippocampus, amygdala and prefrontal cortex, and in epithelial transport tissues (de Kloet et al., 1998; Koning et al., 2019). In the brain, MRs have an approximately 10-fold higher affinity for GCs than GRs, and are primarily occupied during basal, non-stress conditions, contributing to maintaining homeostatic processes, such as fluid balance, baseline circadian tone, environmental appraisal, and vigilance (Reul and de Kloet, 1985; de Kloet, 2022). GRs have lower affinity and, consequently, are engaged at higher GC concentrations, such as during acute stress and circadian peaks, driving energy mobilization, behavioral adaptation, and feedback inhibition of the HPA axis. An optimal balance between MR and GR activation is crucial for appropriate stress regulation and behavioral flexibility (de Kloet and Joëls, 2024). <strong>[Interview Ron de Kloet and Marian Joels]</strong>"}]}$ob$::jsonb, $ob$Glucocorticoid receptors and mechanisms of action: GCs act primarily through two intracellular and membrane receptor types, the mineralocorticoid receptor (MR) and the glucocorticoid receptor (GR).…$ob$, 27, false, NULL, NULL, false, 2);
  -- p28 [text L2] Glucocorticoids exert their biological effects across two distinct time domains corresponding to
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Glucocorticoids exert their biological effects across two distinct time domains corresponding to genomic and non-genomic effects. Their genomic effects, taking place from hours to days, are exerted following GC binding to intracellular GR or MR. This leads to dissociation of the receptor from chaperone proteins, followed by their translocation into the nucleus, where they regulate gene expression by binding directly to glucocorticoid responsive elements (GREs) on DNA or by tethering to other transcription factors (e.g., NK-kB, AP-1), recruiting chromatin-remodeling cofactors to contribute to long-term adaptations to stress, influencing processes such as energy balance, immune regulation and neural plasticity. In addition, GCs can also exert non-genomic actions, taking place from seconds to minutes, via cell membrane-associated pools of MR and GR, whereby they can rapidly influence intracellular signaling cascades and, thus, enabling immediate stress responses (Tasker et al., 2006; Joëls et al., 2012). In the hypothalamus, rapid GC signaling stimulates retrograde endocannabinoid release to suppress excitatory synaptic drive onto PNV neurosecretory neurons, contributing to fast-rate-sensitive feedback (Di et al., 2003). Furthermore, membrane-MR activation can enhance excitatory glutamatergic transmission and neuronal excitability in the hippocampus, promoting vigilance and memory retrieval, while GR activation can modulate synaptic plasticity and potentiate memory consolidation (de Kloet and Joëls, 2024). Thus, through this dual mode of action, with integration of rapid non-genomic and sustained genomic transcription, GCs can provide both immediate and sustained regulation of physiological and behavioral responses to stress."}]}$ob$::jsonb, $ob$Glucocorticoids exert their biological effects across two distinct time domains corresponding to genomic and non-genomic effects. Their genomic effects, taking place from hours to days, are exerted…$ob$, 28, false, NULL, NULL, false, 2);
  -- p29 [text L2] Central regulation and negative feedback of the HPA axis
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Central regulation and negative feedback of the HPA axis</strong>"}]}$ob$::jsonb, $ob$Central regulation and negative feedback of the HPA axis$ob$, 29, false, NULL, NULL, false, 2);
  -- p30 [text L2] The HPA axis activity is not only regulated by its core hypothalamic, pituitary, and adrenal com
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The HPA axis activity is not only regulated by its core hypothalamic, pituitary, and adrenal components, but also by a distributed network of brain regions that integrates sensory, visceral, emotional and cognitive information to determine the magnitude and duration of the response to a given stressor (Ulrich-Lai and Herman, 2009; Herman et al., 2016). These structures modulate HPA activity primarily through direct or, more commonly, multisynaptic inputs to CRH- and AVP-expressing neurons in the PVN, often involving intermediate relays in the bed nucleus of the stria terminalis (BNST) and other hypothalamic regions (Herman et al., 2020). The hippocampus and PFC generally contribute to the restraint of HPA axis activity, whereas amygdala circuits can facilitate its activation, particularly in response to psychologically salient or threat-related stimuli; these influences are heterogeneous across subregions and pathways rather than uniformly excitatory or inhibitory. In parallel, brainstem regions, including the nucleus of the solitary tract and ventrolateral medulla, provide important inputs related to visceral and autonomic information and are particularly important for recruiting the HPA axis in response to physiological challenges (Ulrich-Lai and Herman, 2009; Herman et al., 2016). These influences are highly context-dependent and allow HPA axis recruitment to reflect not only the physical properties of a stressor but also its perceived significance, controllability, prior experience, and the organism’s internal state. <strong>[Interview Jim Herman]</strong>"}]}$ob$::jsonb, $ob$The HPA axis activity is not only regulated by its core hypothalamic, pituitary, and adrenal components, but also by a distributed network of brain regions that integrates sensory, visceral,…$ob$, 30, false, NULL, NULL, false, 2);
  -- p31 [text L2] A major component of this regulation is GC negative feedback, through which rising GC concentrat
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"A major component of this regulation is <strong>GC negative feedback</strong>, through which rising GC concentrations constrain further HPA axis activation and facilitate recovery once the challenge subsides. Feedback operates at multiple levels, including direct actions at the anterior pituitary and PVN, as well as indirect modulation through distributed forebrain and limbic circuits (Keller-Wood and Dallman, 1984; Herman et al., 2016). Feedback also occurs over multiple timescales, including rapid non-genomic mechanisms that can operate within minutes, and intermediate and delayed genomic mechanisms which involve actions through receptor signaling, neuronal excitability, peptide synthesis, and ACTH secretion over longer periods (Di et al., 2003; Tasker et al., 2006; Herman et al., 2016)."}]}$ob$::jsonb, $ob$A major component of this regulation is GC negative feedback, through which rising GC concentrations constrain further HPA axis activation and facilitate recovery once the challenge subsides.…$ob$, 31, false, NULL, NULL, false, 2);
  -- p32 [text L2] MRs and GRs make partly distinct but overlapping contributions to this regulatory process. MRs, 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"MRs and GRs make partly distinct but overlapping contributions to this regulatory process. MRs, due to their higher affinity for endogenous GCs, are substantially occupied under basal conditions and contribute to basal HPA axis tone, anticipatory regulation, appraisal and the threshold for stress-response initiation. GRs become increasingly recruited as GC concentrations rise during the circadian peak and following stress and play a prominent role in constraining the HPA axis response and promoting its termination and promote a return to baseline activity (de Kloet, 2022). This division is relative rather than absolute, as MR- and GR-mediated actions interact across brain regions and timescales. Effective negative feedback, therefore, does not eliminate glucocorticoid signaling; instead, it maintains the appropriate magnitude, temporal organization and termination of GC exposure, thereby protecting the brain and peripheral organs from the harmful effects of prolonged stress responses and preserving the capacity of the HPA axis to respond dynamically to subsequent challenges (de Kloet and Joëls, 2024)."}]}$ob$::jsonb, $ob$MRs and GRs make partly distinct but overlapping contributions to this regulatory process. MRs, due to their higher affinity for endogenous GCs, are substantially occupied under basal conditions and…$ob$, 32, false, NULL, NULL, false, 2);
  -- p33 [text L2] Rhythmicity of the HPA axis activity
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Rhythmicity of the HPA axis activity</strong>"}]}$ob$::jsonb, $ob$Rhythmicity of the HPA axis activity$ob$, 33, false, NULL, NULL, false, 2);
  -- p34 [text L2] The HPA axis operates with distinct circadian and ultradian rhythms, which align GC levels with 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The HPA axis operates with distinct circadian and ultradian rhythms, which align GC levels with the changing demands of the active and rest phases (Russell and Lightman, 2019). Circadian regulation originates principally in the central clock in the brain (the suprachiasmatic nucleus; SCN), but it is executed through a network of neural projections, autonomic innervation, and local clock genes within the adrenal cortex itself, which dynamically gate adrenocortical sensitivity to ACTH (Oster et al., 2006). Glucocorticoid levels rise in an anticipatory manner before and around awakening (daytime for humans and nighttime for nocturnal species like rodents), elevating blood glucose, blood pressure, and neural vigilance to prepare the organism for the energetic demands of wakefulness."}]}$ob$::jsonb, $ob$The HPA axis operates with distinct circadian and ultradian rhythms, which align GC levels with the changing demands of the active and rest phases (Russell and Lightman, 2019). Circadian regulation…$ob$, 34, false, NULL, NULL, false, 2);
  -- p35 [text L2] Superimposed on this daily cycle are ultradian pulses of ACTH and GCs, occurring at approximatel
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Superimposed on this daily cycle are ultradian pulses of ACTH and GCs, occurring at approximately 60- to 120-minute intervals. These pulses emerge naturally from feedback dynamics between the anterior pituitary and the adrenal cortex (Gjerstad et al., 2018). At the cellular level, this pulsatile hormone delivery allows GR signaling to repeatedly activate and reset, preserving tissue sensitivity and preventing receptor desensitization (Stavreva et al., 2009). The functional importance of this pattern is demonstrated by clinical studies in which delivering cortisol in natural pulses produces markedly different cognitive, neural, and emotional effects than giving the exact same total daily amount as a continuous infusion (Kalafatakis et al., 2018). This illustrates that the timing and rhythm of hormone release carry critical biological signals, not just the total hormone concentration. Disruption of these rhythms, such as flattened daily curves, elevated nighttime baselines, or blunted pulses, is commonly observed in chronic stress, metabolic dysfunction, depression, and systemic inflammatory disorders (Russell and Lightman, 2019; Agorastos and Chrousos, 2022)."}]}$ob$::jsonb, $ob$Superimposed on this daily cycle are ultradian pulses of ACTH and GCs, occurring at approximately 60- to 120-minute intervals. These pulses emerge naturally from feedback dynamics between the…$ob$, 35, false, NULL, NULL, false, 2);
  -- p36 [text L2] Systems modulated by glucocorticoids during stress
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Systems modulated by glucocorticoids during stress</strong>"}]}$ob$::jsonb, $ob$Systems modulated by glucocorticoids during stress$ob$, 36, false, NULL, NULL, false, 2);
  -- p37 [text L2] GCs play multiple roles in the stress response, complementing, enabling, constraining, and reorg
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"GCs play multiple roles in the stress response, complementing, enabling, constraining, and reorganizing the rapid physiological actions initiated by the SNS. GC actions are classically categorized as permissive, suppressive, stimulatory, and preparative effects (Munck et al., 1984; Sapolsky et al., 2000) that together contribute to robust stress responding to meet metabolic challenges while preserving primary defense mechanisms from overshooting and damaging host tissues."}]}$ob$::jsonb, $ob$GCs play multiple roles in the stress response, complementing, enabling, constraining, and reorganizing the rapid physiological actions initiated by the SNS. GC actions are classically categorized…$ob$, 37, false, NULL, NULL, false, 2);
  -- p38 [text L2] Metabolism: GCs sustain energy mobilization initiated by the SNS by enhancing hepatic gluconeoge
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Metabolism:</strong> GCs sustain energy mobilization initiated by the SNS by enhancing hepatic gluconeogenesis and increasing the supply of gluconeogenic precursors (such as amino acids mobilized from muscle breakdown and glycerol from adipose tissue) (Rose and Herzig, 2013). Simultaneously, GCs induce transient insulin resistance in skeletal muscle and adipose tissue, reducing glucose uptake by peripheral tissues, and prioritizing blood glucose levels and making energy continuously available for the brain and muscles during prolonged stress. GCs can also modulate lipid metabolism with effects depending on context; while acute elevations facilitate catecholamine-mediated lipolysis, chronic GC excess promotes visceral adiposity, hypersinsulinemia, and metabolic dysfunction (Peckett et al., 2011; Rose and Herzig, 2013)"}]}$ob$::jsonb, $ob$Metabolism: GCs sustain energy mobilization initiated by the SNS by enhancing hepatic gluconeogenesis and increasing the supply of gluconeogenic precursors (such as amino acids mobilized from muscle…$ob$, 38, false, NULL, NULL, false, 2);
  -- p39 [text L2] Cardiovascular system: At physiological concentrations, GCs exert essential permisive effects th
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Cardiovascular system:</strong> At physiological concentrations, GCs exert essential permisive effects that maintain vascular sensitivity to catecholamines and other vasoconstrictors, thereby supporting blood pressure stability, cardiac output, and appropriate blood flow redistribution during stress (Yang and Zhang, 2004; Walker, 2007). Complementing rapid SNS-induced vascular adjustments, GCs sustain vascular tone over extended periods, contributing to the redistribution of blood flow toward muscles and vital organs. However, prolonged or excessive GC exposure promotes cardiovascular pathology, including hypertension and endothelial dysfunction (Walker, 2007)."}]}$ob$::jsonb, $ob$Cardiovascular system: At physiological concentrations, GCs exert essential permisive effects that maintain vascular sensitivity to catecholamines and other vasoconstrictors, thereby supporting…$ob$, 39, false, NULL, NULL, false, 2);
  -- p40 [text L2] Immune system: GCs act as potent immunomodulators whose actions depend on hormone concentration,
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Immune system:</strong> GCs act as potent immunomodulators whose actions depend on hormone concentration, exposure duration, and the timing of the immune challenge (Rhen and Cidlowski, 2005; Cain and Cidlowski, 2017). At physiological stress levels, early GC signals can have permissive or preparative effects, guiding leukocyte trafficking to frontline barrier tissues (Dhabhar et al., 2012). As GC concentrations peak , they exert protective suppressive actions by inhibiting transcription factors (such as NF-kB and AP-1), downregulating pro-inflammatory cytokines while promoting the synthesis of anti-inflammatory ones (Munck et al., 1984; Sapolsky et al., 2000; Dhabhar et al., 2012), helping to limit tissue damage and support resolution of the immune response after acute immune activation."}]}$ob$::jsonb, $ob$Immune system: GCs act as potent immunomodulators whose actions depend on hormone concentration, exposure duration, and the timing of the immune challenge (Rhen and Cidlowski, 2005; Cain and…$ob$, 40, false, NULL, NULL, false, 2);
  -- p41 [text L2] Altogether, the actions of GCs integrate and fine-tune the stress response by interacting dynami
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Altogether, the actions of GCs integrate and fine-tune the stress response by interacting dynamically with catecholamines, neuropeptides, and local tissue mediators. This dynamic interplay allows the organism to respond effectively to immediate threats while avoiding long-term damage and facilitating adaptation, a dynamic homeostatic process known as allostasis (McEwen, 1998). When this regulation fails through chronic, exaggerated, or blunted activation, allostatic load accumulates, increasing vulnerability to metabolic, cardiovascular, and systemic pathologies (McEwen and Wingfield, 2003; Agorastos and Chrousos, 2022)."}]}$ob$::jsonb, $ob$Altogether, the actions of GCs integrate and fine-tune the stress response by interacting dynamically with catecholamines, neuropeptides, and local tissue mediators. This dynamic interplay allows…$ob$, 41, false, NULL, NULL, false, 2);
  -- p42 [level-2 header] Neurochemical stress responses in the brain
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":4,"content":"Neurochemical stress responses in the brain"}]}$ob$::jsonb, $ob$Neurochemical stress responses in the brain$ob$, 42, false, NULL, NULL, true, 2);
  -- p43 [text L2] The brain’s response to stress relies on a diverse array of mediators, including neurotransmitte
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The brain’s response to stress relies on a diverse array of mediators, including neurotransmitters, neuropeptides, and GCs, as well as lipid-derived messengers and immune and metabolic signals, each contributing to adaptive responses at different timescales. Their actions overlap and interact, from rapid synaptic transmission and non-genomic signaling to slower transcriptional, epigenetic, and structural adaptations (Joëls and Baram, 2009; Joëls et al., 2012; Lugenbühl et al., 2025). Together, these mediators modulate neural circuits responsible for vigilance, emotional regulation, memory, and physiological adaptations (Joëls and Baram, 2009). Their effects depend on a myriad of factors, from the identity and concentration of the mediator, to the receptor subtype, cell type, brain region, timing relative to the stressor, circadian phase, and psychological factors (Joëls and Baram, 2009; McEwen, 2007; Lugenbühl et al., 2025)."}]}$ob$::jsonb, $ob$The brain’s response to stress relies on a diverse array of mediators, including neurotransmitters, neuropeptides, and GCs, as well as lipid-derived messengers and immune and metabolic signals, each…$ob$, 43, false, NULL, NULL, false, 2);
  -- p44 [text L2] Neurotransmitters and monoamines: Classical fast-acting neurotransmitters and neuromodulatory mo
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Neurotransmitters and monoamines:</strong> Classical fast-acting neurotransmitters and neuromodulatory monoamines provide the earliest central responses to acute threat. Glutamate and GABA rapidly rebalance local excitation and inhibition across cortical, limbic, and hypothalamic networks, gating fast synaptic plasticity and immediate behavioral reactivity (Popoli et al., 2012; Bains et al., 2015). Concurrently, ascending monoaminergic systems, including NE from the LC, dopamine from the ventral tegmental area and substantia nigra, and serotonin from the raphe nuclei, project broadly to regions such as the PFC, amygdala, and hippocampus to adjust network operating states (Aston-Jones and Cohen, 2005; Morales and Margolis, 2017). NE increases vigilance, sensory gain, and environmental scanning, reallocating neural resources toward salience detection at the expense of reflective executive processing (Aston-Jones and Cohen, 2005; Arnsten, 2009). Dopamine release modulates motivational salience, action selection, and working memory, often following an inverted-U relationship where intermediate levels optimize PFC function while extreme states impair flexible cognition (Vijayraghavan et al., 2007; Holly and Miczek, 2016). Serotonergic signaling shapes emotional processing, behavioral inhibition, and coping strategies, with distinct receptor subtypes and circuits exerting divergent effects on anxiety and threat resolution (Marcinkiewicz et al., 2016; Seo et al., 2019). Acting through both ionotropic channels and G protein-coupled receptors, these neurotransmitters drive rapid, context-dependent adaptations to acute challenges."}]}$ob$::jsonb, $ob$Neurotransmitters and monoamines: Classical fast-acting neurotransmitters and neuromodulatory monoamines provide the earliest central responses to acute threat. Glutamate and GABA rapidly rebalance…$ob$, 44, false, NULL, NULL, false, 2);
  -- p45 [text L2] Neuropeptides and lipid messengers: Neuropeptides are frequently co-released with fast neurotran
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Neuropeptides and lipid messengers:</strong> Neuropeptides are frequently co-released with fast neurotransmitters during periods of sustained or high-frequency neuronal firing, exerting prolonged actions that tune circuit excitability and neural plasticity (van den Pol, 2012; Bains et al., 2015). Beyond its hypothalamic role in the PVN, CRH also acts centrally in brain regions, such as the amygdala, BNST and hippocampus, where it enhances arousal, vigilance, and the encoding of emotionally salient events (Bale and Vale, 2004). AVP, similarly modulates emotional processing, anxiety-related behaviors and social appraisal through distributed limbic networks (Caldwell et al., 2008)."}]}$ob$::jsonb, $ob$Neuropeptides and lipid messengers: Neuropeptides are frequently co-released with fast neurotransmitters during periods of sustained or high-frequency neuronal firing, exerting prolonged actions…$ob$, 45, false, NULL, NULL, false, 2);
  -- p46 [text L2] Other neuropeptidergic systems can counteract stress responses; e.g., neuropeptide Y (NPY) acts 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Other neuropeptidergic systems can counteract stress responses; e.g., neuropeptide Y (NPY) acts in the amygdala to promote anxiolysis and stress resilience (Heilig, 2004), while oxytocin modulates stress reactivity by attenuating emotional responses and enhancing the salience of social cues (Shamay-Tsoory and Abu-Akel, 2016; Grinevich and Neumann, 2021). Furthermore, retrograde lipid messengers such as en endocannabinoids provide crucial rapid feedback, acting on presynaptic CB1 receptors to constrain excessive glutamate and GABA release and, thus, facilitating post-stress recovery and circuit reset (Di et al., 2003; Joëls et al., 2012)."}]}$ob$::jsonb, $ob$Other neuropeptidergic systems can counteract stress responses; e.g., neuropeptide Y (NPY) acts in the amygdala to promote anxiolysis and stress resilience (Heilig, 2004), while oxytocin modulates…$ob$, 46, false, NULL, NULL, false, 2);
  -- p47 [text L2] Glucocorticoids integration: GCs released by the adrenal glands to the bloodstream can readily c
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Glucocorticoids integration:</strong> GCs released by the adrenal glands to the bloodstream can readily cross the blood-brain barrier and act in the brain through binding to MRs and GRs, which are widely distributed throughout the brain. GCs regulate gene expression, synaptic plasticity, and other aspects of neuronal functioning. For example, GCs can promote plasticity and enhance the consolidation of memories. However, chronic or excessive GC elevation, as it occurs in chronic stress, has been shown to lead to impairments in neurogenesis and functional connectivity, and these effects may contribute to stress-related pathologies (see next section)."}]}$ob$::jsonb, $ob$Glucocorticoids integration: GCs released by the adrenal glands to the bloodstream can readily cross the blood-brain barrier and act in the brain through binding to MRs and GRs, which are widely…$ob$, 47, false, NULL, NULL, false, 2);
  -- p48 [text L2] Crucially, these fast neurotransmitters and neuropeptides do not operate in isolation from syste
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Crucially, these fast neurotransmitters and neuropeptides do not operate in isolation from systemic endocrine systems. As circulating GCs enter the brain, they integrate directly with ongoing synaptic transmission; for example, by acting synergistically with noradrenergic and glutamatergic signaling in the amygdala to modulate the encoding of salient events (Roozendaal et al., 2009). This intricate neurochemical orchestration of stress mediators ensures that the brain can rapidly detect threats, execute immediate defense strategies, and subsequently engage genomic mechanisms promoting adaptation. How these responses reshape specific brain structures, neural circuits, and cognitive functions across different timescales is the focus of the next section."}]}$ob$::jsonb, $ob$Crucially, these fast neurotransmitters and neuropeptides do not operate in isolation from systemic endocrine systems. As circulating GCs enter the brain, they integrate directly with ongoing…$ob$, 48, false, NULL, NULL, false, 2);
  -- p49 [level-2 header] Cellular metabolism and mitochondria in the stress response
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":4,"content":"Cellular metabolism and mitochondria in the stress response"}]}$ob$::jsonb, $ob$Cellular metabolism and mitochondria in the stress response$ob$, 49, false, NULL, NULL, true, 2);
  -- p50 [text L2] Stress responses mediated by the SNS and HPA axis require cells in the body to adjust their ener
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Stress responses mediated by the SNS and HPA axis require cells in the body to adjust their energy production and metabolic activity. Mitochondria are central to this adaptation. These intracellular organelles contribute much of the cellular energy required to meet changing demands, in addition to participating in many other functions, including metabolic, calcium and redox signaling. Importantly, mitochondria are themselves integral to the production of steroid hormones. Specifically, in the adrenal cortex, key steps in the conversion of cholesterol into glucocorticoids takes place within mitochondria. Thus, mitochondria operate both downstream of stress mediators, by adjusting cellular function to changing physiological demands, and upstream of them, by enabling production of one of the principal hormonal outputs of the stress response, glucocorticoids (Miller and Auchus, 2011; Meimaridou et al., 2012)."}]}$ob$::jsonb, $ob$Stress responses mediated by the SNS and HPA axis require cells in the body to adjust their energy production and metabolic activity. Mitochondria are central to this adaptation. These intracellular…$ob$, 50, false, NULL, NULL, false, 2);
  -- p51 [text L2] Experimental evidence indicates that mitochondria can actively shape the magnitude and coordinat
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Experimental evidence indicates that mitochondria can actively shape the magnitude and coordination of systemic stress responses, including the degree and pattern of activation of SNS and HPA axis, along with the specific impact of stress in metabolic, inflammatory and transcriptional responses (Picard et al., 2015). In the brain, mitochondria similarly support the energetic and signaling requirements of neurons and glial cells, contributing to synaptic transmission, circuit function, behaviour and cognition, as well as contributing to stress effects (Sandi et al., 2026). During chronic stress, persistent alterations in mitochondrial function may contribute to maladaptive cellular and circuit changes and,more broadly, to the accumulation of allostatic load (Picard and McEwen, 2018; Kelley et al., 2025). Mitochondria therefore provide an important cellular link between the body's energetic and endocrine adaptations to stress and the changes in brain structure and function discussed in the following sections."}]}$ob$::jsonb, $ob$Experimental evidence indicates that mitochondria can actively shape the magnitude and coordination of systemic stress responses, including the degree and pattern of activation of SNS and HPA axis,…$ob$, 51, false, NULL, NULL, false, 2);

  -- Section 2: Stress effects on behavior and brain structure and function
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Stress effects on behavior and brain structure and function$ob$, $ob$stress-effects-on-behavior-and-brain-structure-and-function$ob$, 2, NULL);
  -- p0 [text L0] Stress profoundly impacts both brain structure and function, and consequently, behavior and cogni
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Stress profoundly impacts both brain structure and function, and consequently, behavior and cognition. Acute stress responses are frequently adaptive, facilitating survival through rapid behavioral and cognitive adjustments. In contrast, chronic stress can lead to widespread structural and functional changes in key brain regions, often disrupting cognitive processes and promoting maladaptive behavioral patterns."}]}$ob$::jsonb, $ob$Stress profoundly impacts both brain structure and function, and consequently, behavior and cognition. Acute stress responses are frequently adaptive, facilitating survival through rapid behavioral…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [level-1 header] Behavioral and cognitive outcomes of stress
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Behavioral and cognitive outcomes of stress"}]}$ob$::jsonb, $ob$Behavioral and cognitive outcomes of stress$ob$, 1, false, NULL, NULL, true, 1);
  -- p2 [text L1] Stress is a powerful modulator of behavior and cognition, exerting diverse effects on social beha
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Stress is a powerful modulator of behavior and cognition, exerting diverse effects on social behaviors, learning and memory, and decision-making that typically differ between acute and chronic stress situations."}]}$ob$::jsonb, $ob$Stress is a powerful modulator of behavior and cognition, exerting diverse effects on social behaviors, learning and memory, and decision-making that typically differ between acute and chronic…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Social behaviors: Stress influences social behaviors in particularly complex and context-dependen
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Social behaviors:</strong> Stress influences social behaviors in particularly complex and context-dependent ways as, in addition to the impact of stress on the individual itself, other interacting individuals can represent sources of threat or competition, but also safety, affiliation and support (Sandi and Haller, 2015). Accordingly, stress effects in social behaviors are situation-dependent. During acute stress, perceived social threat may promote withdrawal, vigilance, submission, or defensive aggression, whereas the presence of familiar or supportive individuals tend to increase affiliation and proximity seeking. Acute psychosocial stress has also been shown to increase trust, sharing and other prosocial behaviors under some conditions, depending on the social context and the interaction partner (von Dawans et al., 2012; Nitschke et al., 2022). The emerging picture is, therefore, that acute stress can both favor affiliation towards individuals perceived as safe or able to provide support, and avoidance or defensive responses when the individuals are perceived as threatening."}]}$ob$::jsonb, $ob$Social behaviors: Stress influences social behaviors in particularly complex and context-dependent ways as, in addition to the impact of stress on the individual itself, other interacting…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [text L1] On the other hand, intense or chronic stress frequently promotes social withdrawal and avoidance,
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"On the other hand, intense or chronic stress frequently promotes social withdrawal and avoidance, and irritability and reactive aggression can increase, particularly in adverse or threatening social environments or when individuals perceive a threat to their safety or status (Sandi and Haller, 2015). Importantly, stress effects show marked individual variability; individual characteristics, such as trait anxiety or social rank, and stress during sensitive developmental periods further modulate these effects, with lasting impacts on social behavior (Krishnan et al., 2007; Sandi and Haller, 2015). Conversely, positive social relationships can buffer the negative impact of stress (Hostinar et al., 2014)."}]}$ob$::jsonb, $ob$On the other hand, intense or chronic stress frequently promotes social withdrawal and avoidance, and irritability and reactive aggression can increase, particularly in adverse or threatening social…$ob$, 4, false, NULL, NULL, false, 1);
  -- p5 [text L1] Learning and memory: Stress affects learning and memory in multiple ways, depending on key factor
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Learning and memory:</strong> Stress affects learning and memory in multiple ways, depending on key factors such as stressor intensity and the cognitive phase during which stress occurs (de Quervain et al., 2017). In general, acute stress facilitates memory consolidation but impairs information retrieval and working memory. However, the effects of acute stress on declarative or explicit memory processes often follow an inverted U-shaped function, where moderate stress levels enhance memory performance, while very low or very high stress levels impair it. In contrast, implicit memory processes, such as procedural learning, tend to show a linear relationship with stress intensity, with increasing stress progressively enhancing performance in these tasks. Chronic stress, on the other hand, typically impairs hippocampal-dependent memory processes, such as spatial and declarative learning, while favoring amygdala-driven emotional and fear related memory consolidation. Furthermore, chronic stress tends to also impair prefrontal cortex-related functions, such as executive processes, including working memory and cognitive flexibility, and promote reliance on dorsal-striatum-dependent habitual learning systems instead of ventral-striatum-dependent goal-directed ones. <strong>[Interview Lars Schwabe]</strong>"}]}$ob$::jsonb, $ob$Learning and memory: Stress affects learning and memory in multiple ways, depending on key factors such as stressor intensity and the cognitive phase during which stress occurs (de Quervain et al.,…$ob$, 5, false, NULL, NULL, false, 1);
  -- p6 [text L1] Decision-making: Stress can also alter decision-making by changing how potential outcomes are val
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Decision-making:</strong> Stress can also alter decision-making by changing how potential outcomes are valued and the strategies used to select actions. During acute stress, decisions under uncertainty can become more reward-seeking or risk-prone under some conditions, but these effects are relatively small and strongly dependent on the nature and timing of the decision and the stress response (Starcke and Brand, 2016; Schettino et al., 2024). Indeed, risk preferences can change dynamically even within the first hour following stress, in line with the dynamics of SNS and HPA axis responses. In one study, participants shifted from lower risk aversion shortly after exposure to psychosocial stress to greater risk aversion at later time points, highlighting the importance of the evolving temporal dynamics of the stress response for decision-making (Bendahan et al., 2017). Moreover, stress can affect self- and other-regarding decisions differently, reducing consideration of negative consequences for another person when risk carries an antisocial outcome (Bendahan et al., 2017). Although with variability across conditions and individuals (Smeets et al., 2023), acute stress can also reduce sensitivity to action outcome and bias behavioral control away from flexible, goal-directed strategies towards more habitual and automated responses, particularly when glucocorticoid and noradrenergic systems are concurrently activated (Schwabe and Wolf, 2009; Schwabe et al., 2012). During chronic stress exposure, reduced sensitivity to action outcomes and greater reliance on habitual strategies can become more persistent, and are associated with structural and functional reorganization of frontostriatal circuits (Dias-Ferreira et al., 2009). Thus, particularly when stress is prolonged, decision-making can become less flexible and goal-directed to more habitual and rigid, less sensitive to changes in the consequences of actions."}]}$ob$::jsonb, $ob$Decision-making: Stress can also alter decision-making by changing how potential outcomes are valued and the strategies used to select actions. During acute stress, decisions under uncertainty can…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [level-1 header] Stress-induced structural and functional changes in key brain regions
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Stress-induced structural and functional changes in key brain regions"}]}$ob$::jsonb, $ob$Stress-induced structural and functional changes in key brain regions$ob$, 7, false, NULL, NULL, true, 1);
  -- p8 [text L1] The behavioral and cognitive outcomes of stress are underpinned by neurobiological changes in a n
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The behavioral and cognitive outcomes of stress are underpinned by neurobiological changes in a network of brain regions, including the hippocampus, amygdala, PFC, and striatum. These regions are not involved separately; instead, they are interconnected components of larger neural circuits that are dynamically remodelled during stress (Hermans et al., 2011; McEwen et al., 2016). Stress-induced changes in these regions vary with the intensity and duration of the stressor, involving both acute and chronic adaptations mediated, among others, by GCs, catecholamines and other stress mediators. Acute stress often induces rapid, transient changes that support adaptive responses, while chronic stress can produce more persistent structural remodeling of synapses and dendritic architecture, changes in gene regulation and neurogenesis, and alterations in functional connectivity (McEwen et al., 2016). Across regions, these adaptations engage region- and cell-specific synaptic, intracellular, neurotrophic and neuroimmune mechanisms (Lugenbühl et al., 2025), but they should not be automatically interpreted as neuronal damage. Indeed, stress-induced neural remodeling can initially represent an adaptive response that reallocates neural resources towards processes most relevant to the challenge. However, when stress becomes chronic, these adaptations can become maladaptive. Importantly, many stress-induced changes can be partly reversible once stress has ceased, although their persistence depends on the specific brain region, developmental stage and previous stress exposure (Lupien et al., 2009; McEwen et al., 2016; Radley and Herman, 2023)."}]}$ob$::jsonb, $ob$The behavioral and cognitive outcomes of stress are underpinned by neurobiological changes in a network of brain regions, including the hippocampus, amygdala, PFC, and striatum. These regions are…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [text L1] Hippocampus: The hippocampus, a key structure for memory and stress regulation, exhibits dynamic 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Hippocampus:</strong> The hippocampus, a key structure for memory and stress regulation, exhibits dynamic responses to acute and chronic stress that vary across its different subregions (McEwen et al., 2016). During acute stress, hippocampal function is rapidly reconfigured through the combined actions of GCs, NE, glutamate and other stress mediators on neuronal excitability and synaptic transmission. Within minutes, membrane-associated MR-mediated GC actions can increase glutamatergic transmission and neuronal excitability. As GC concentrations rise and GRs become increasingly recruited, synaptic plasticity is altered. For example, in the CA1 subregion, acute stress preceding plasticity induction typically suppresses long-term potentiation (LTP) and facilitates long-term depression (LTD) (Karst et al., 2005; Yang et al., 2004; Chaouloff et al., 2007). GR activation can also induce rapid structural plasticity, including changes in dendritic spine formation, providing a structural correlate of these acute changes in synaptic function (Komatsuzaki et al., 2012). Over the hours following stress induction, slower transcription-dependent GC actions further modify synaptic responsiveness and determine how readily hippocampal circuits can subsequently undergo plasticity (Joëls et al., 2006, 2012). Importantly, although their magnitude and persistence can vary with stressor intensity, these acute changes are generally transient."}]}$ob$::jsonb, $ob$Hippocampus: The hippocampus, a key structure for memory and stress regulation, exhibits dynamic responses to acute and chronic stress that vary across its different subregions (McEwen et al.,…$ob$, 9, false, NULL, NULL, false, 1);
  -- p10 [text L1] In contrast, chronic stress can produce more persistent structural and functional remodeling of 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"In contrast, chronic stress can produce more persistent structural and functional remodeling of hippocampal circuits. One of the most consistently observed changes is retraction and reduced branching of the apical dendrites of CA3 pyramidal neurons, along with reductions in dendritic spines and synaptic connectivity (Watanabe et al., 1992; Magariños and McEwen, 1995; McEwen et al., 2016). Related changes in dendritic architecture and synaptic efficacy have also been reported in CA1 and the dentate gyrus (McEwen et al., 2016). Importantly, this structural remodeling does not imply widespread neuronal loss, and CA3 dendritic retraction can substantially recover following stress cessation (Hoffman et al., 2011; McEwen et al., 2016). Chronic stress can also suppress adult hippocampal neurogenesis in the dentate gyrus, although the magnitude of this effect depends on factors such as age, sex and stressor characteristics (Gould et al., 1997; Snyder et al., 2011). At the functional level, chronic stress can impair hippocampal synaptic efficacy and plasticity, including LTP, with consequences for information processing and stress-related deficits in learning and memory (Krugers et al., 2006; McEwen et al., 2016)."}]}$ob$::jsonb, $ob$In contrast, chronic stress can produce more persistent structural and functional remodeling of hippocampal circuits. One of the most consistently observed changes is retraction and reduced…$ob$, 10, false, NULL, NULL, false, 1);
  -- p11 [text L1] Amygdala: The amygdala, a central structure for processing emotional and threat-related stimuli,
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Amygdala:</strong> The amygdala, a central structure for processing emotional and threat-related stimuli, also exhibits distinct responses to acute and chronic stress. During acute stress, neuronal activity and synaptic transmission are rapidly altered, particularly within the basolateral amygdala (BLA). Noradrenergic and GC signaling interact in the BLA, where they can facilitate synaptic plasticity and the consolidation of emotionally salient experiences (McGaugh, 2004; Hermans et al., 2011). When stress intensity is high, it can produce long-lasting effects, as illustrated by work in rodents in which a single intense stress exposure was shown to induce delayed increases in BLA dendritic spine density and strengthening of excitatory transmission over subsequent days (Mitra et al., 2005; Yasmin et al., 2016)."}]}$ob$::jsonb, $ob$Amygdala: The amygdala, a central structure for processing emotional and threat-related stimuli, also exhibits distinct responses to acute and chronic stress. During acute stress, neuronal activity…$ob$, 11, false, NULL, NULL, false, 1);
  -- p12 [text L1] When chronic, stress-induced structural remodeling of the amygdala becomes more pronounced. Foll
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"When chronic, stress-induced structural remodeling of the amygdala becomes more pronounced. Following exposure to different well-established rodent paradigms, BLA principal neurons have been shown to exhibit dendritic hypertrophy and increased spine density, in marked contrast to the dendritic atrophy typically observed in the hippocampal CA3 and mPFC neurons (Vyas et al., 2002; Mitra et al., 2005; McEwen et al., 2016). These structural changes can persist after stress cessation and can be accompanied by enhanced excitatory drive and synaptic plasticity, together with reduced inhibitory tone, resulting in a more excitable BLA network (Vyas et al., 2004; Padival et al., 2013). However, this pattern is not uniform throughout the amygdala, as different nuclei and neuronal populations can exhibit distinct forms of stress-induced remodeling (Vyas et al., 2003; McEwen et al., 2016). Together, these structural and functional adaptations can produce long-lasting changes in amygdala responsivity and in its communication with cortical, hippocampal and striatal circuits (Vyas et al., 2004; McEwen et al., 2016)."}]}$ob$::jsonb, $ob$When chronic, stress-induced structural remodeling of the amygdala becomes more pronounced. Following exposure to different well-established rodent paradigms, BLA principal neurons have been shown…$ob$, 12, false, NULL, NULL, false, 1);
  -- p13 [text L1] Prefrontal cortex: The prefrontal cortex, critical for executive functions such as working memor
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Prefrontal cortex:</strong> The prefrontal cortex, critical for executive functions such as working memory, cognitive flexibility, and emotional regulation, is particularly sensitive to stress (Arnsten, 2009). During acute stress, rapid increases in NE and dopamine alter the recurrent neuronal activity that supports these functions. The effects of these catecholamine actions tend to follow an inverted-U relationship, with moderate levels strengthening PFC network function through α2A-adrenergic and D1 receptors, whereas the higher concentrations reached during intense or uncontrollable stress increasingly recruit α1- and β-adrenergic receptors, as well as excessive D1-receptor signaling. The latter, through activation of PKA and calcium-dependent pathways, impairs synaptic efficiency and network connectivity, transiently reducing the PFC’s capacity to support top-down control of behavior and emotional regulation during acute stress exposure (Vijayraghavan et al., 2007; Wang et al., 2007; Arnsten, 2009)."}]}$ob$::jsonb, $ob$Prefrontal cortex: The prefrontal cortex, critical for executive functions such as working memory, cognitive flexibility, and emotional regulation, is particularly sensitive to stress (Arnsten,…$ob$, 13, false, NULL, NULL, false, 1);
  -- p14 [text L1] Chronic stress, on the other hand, can produce more persistent changes in PFC structure and syna
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Chronic stress, on the other hand, can produce more persistent changes in PFC structure and synaptic function, including dendritic retraction and synaptic loss in layer II/III pyramidal neurons, particularly in the medial PFC (mPFC) (Cook and Wellman, 2004; Radley et al., 2006; Liston et al., 2006). These structural changes are accompanied by changes in excitatory and inhibitory transmission including, for example, reductions in AMPA and NMDA receptor expression and glutamatergic synaptic efficacy, compromising PFC network function and plasticity (Yuen et al., 2012), and are associated with impairments in PFC-dependent functions, including attentional control, working memory and behavioral flexibility. However, while mPFC subregions commonly exhibit stress-induced dendritic retraction, notably the mPFC, some areas, such as the orbitofrontal cortex (OFC), can undergo dendritic expansion under some chronic stress paradigms (Liston et al., 2006). In humans, sustained psychosocial stress has similarly been associated with disrupted PFC network connectivity and attentional control, with recovery observed following reduction of the stress exposure (Liston et al., 2009). Together, these structural and functional adaptations can compromise the stability and flexibility of PFC network function and reconfigure its interactions with subcortical circuits, such as the amygdala, contributing to imbalances in emotional and cognitive processing (Arnsten, 2009; McEwen et al., 2016)."}]}$ob$::jsonb, $ob$Chronic stress, on the other hand, can produce more persistent changes in PFC structure and synaptic function, including dendritic retraction and synaptic loss in layer II/III pyramidal neurons,…$ob$, 14, false, NULL, NULL, false, 1);
  -- p15 [text L1] Striatum: The striatum, a key component of corticostriatal circuits involved in action selection
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>Striatum:</strong> The striatum, a key component of corticostriatal circuits involved in action selection, reward-guided learning, motivation and the balance between flexible and habitual behavior, exhibits stress-induced shifts in the functional balance between its different functional circuits. During acute stress, striatal function is rapidly modified through changes in neuromodulatory signaling and corticostriatal processing. Specifically, acute stress can reduce sensitivity to action outcomes and attenuate ventral striatal processing of reward and motivational value, while biasing behavioral control away from flexible, goal-directed processes and towards more habitual and automated responses associated with dorsal, particularly dorsolateral, striatal circuits (Schwabe and Wolf, 2009; Schwabe et al., 2010, 2012; Oei et al., 2014)."}]}$ob$::jsonb, $ob$Striatum: The striatum, a key component of corticostriatal circuits involved in action selection, reward-guided learning, motivation and the balance between flexible and habitual behavior, exhibits…$ob$, 15, false, NULL, NULL, false, 1);
  -- p16 [text L1] Under chronic stress, these functional changes can be accompanied by more persistent structural 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Under chronic stress, these functional changes can be accompanied by more persistent structural reorganization of frontostriatal circuits, leading to a shift in the balance between associative and sensorimotor corticostriatal systems (Sousa, 2016). In rodents, chronic stress induces dendritic retraction in the mPFC and associative dorsomedial striatum (DMS), while promoting dendritic expansion in the sensorimotor dorsolateral striatum (DLS), with these opposing structural changes accompanying reduced sensitivity to action outcomes and greater reliance on habitual strategies (Dias-Ferreira et al., 2009). Recent circuit-level studies further show that distinct amygdala inputs to the DMS are differentially affected, with suppression of the BLA-DMS pathway that supports action-outcome learning and progressive recruitment of a central amygdala-DMS pathway that promotes habit formation (Giovanniello et al., 2025). Thus, these prolonged alterations in striatal networks under chronic stress generally reduce behavioral flexibility while favoring more rigid action strategies."}]}$ob$::jsonb, $ob$Under chronic stress, these functional changes can be accompanied by more persistent structural reorganization of frontostriatal circuits, leading to a shift in the balance between associative and…$ob$, 16, false, NULL, NULL, false, 1);
  -- p17 [level-1 header] Sex differences
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Sex differences"}]}$ob$::jsonb, $ob$Sex differences$ob$, 17, false, NULL, NULL, true, 1);
  -- p18 [text L1] The stress response is now understood to be a highly sex-dependent phenomenon. Historically, res
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The stress response is now understood to be a highly sex-dependent phenomenon. Historically, research often assumed only minor variations between the sexes, but a growing body of recent evidence decisively points to substantial differences in how males and females perceive, process, and respond to stressors at both physiological and psychological levels (Hodes et al., 2024; Stadtler and Neigh, 2023). This differential responding originates from a complex interplay of biological factors, including the impact of sex chromosomes, divergent developmental trajectories influenced by genetic and hormonal cues, and the ongoing impact of gonadal hormones throughout life (Bale and Epperson, 2015)."}]}$ob$::jsonb, $ob$The stress response is now understood to be a highly sex-dependent phenomenon. Historically, research often assumed only minor variations between the sexes, but a growing body of recent evidence…$ob$, 18, false, NULL, NULL, false, 1);
  -- p19 [text L1] At the neuroendocrine level, these organizational and activational influences contribute to mark
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"At the neuroendocrine level, these organizational and activational influences contribute to marked differences in HPA axis regulation. In many rodent paradigms, females exhibit greater HPA axis activity than males, with ovarian steroids, particularly estradiol, generally enhancing basal and stress-induced GC secretion, whereas circulating androgens tend to exert an inhibitory effect on HPA axis activity by reducing CRH expression within the paraventricular nucleus of the hypothalamus (Heck and Handa, 2019; Seale et al., 2004; Bale and Epperson, 2015). However, the opposite pattern has been reported in humans, with men typically showing larger ACTH and cortisol responses to psychosocial stress paradigms, and women showing varied HPA reactivity depending on reproductive and hormonal status (Kirschbaum et al., 1999; Stephens et al., 2016). Beyond systemic hormonal output, sex differences extend to receptor-level dynamics and circuit-specific plasticity. For instance, sex-specific variations in CRH receptor signaling and internalization within the locus coeruleus in mice influence locus coeruleus-norepinephrine (LC-NE) arousal systems and may contribute to greater susceptibility to stress-induced hyperarousal in females (Bangasser et al., 2013). Moreover, sex-specific interactions between gonadal steroids and downstream molecular signaling pathways can exert divergent effects on synaptic plasticity and circuit remodeling, for example in the PFC, establishing a neural basis for observed sex differences in neural responses, vulnerability to stress and mood disorder prevalence (Shansky et al., 2004, 2010; Garrett and Wellman, 2009). Furthermore, the long-term consequences of stress exposure early in life are likewise highly influenced by biological sex, as illustrated by multiple examples of sex-specific manifestations across molecular, circuit, metabolic and behavioral levels (Narayan et al., 2026 PNAS)."}]}$ob$::jsonb, $ob$At the neuroendocrine level, these organizational and activational influences contribute to marked differences in HPA axis regulation. In many rodent paradigms, females exhibit greater HPA axis…$ob$, 19, false, NULL, NULL, false, 1);
  -- p20 [text L1] These sex-dependent features of stress biology may contribute to differences in the vulnerabilit
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"These sex-dependent features of stress biology may contribute to differences in the vulnerability to and manifestation of stress-related disorders. Such conditions are also highly sex-dependent, exhibiting distinct prevalence rates in women and men. For instance, women experience higher rates of major depression, most anxiety disorders, and post-traumatic stress disorder (PTSD), while men show higher rates of many substance use disorders (Cover et al., 2014; McLean et al., 2011; Salk et al., 2017; Koenen et al., 2017; McHugh et al., 2018). This growing understanding underscores the critical need to consider sex as a fundamental biological variable in both the study and treatment of stress and its associated pathologies."}]}$ob$::jsonb, $ob$These sex-dependent features of stress biology may contribute to differences in the vulnerability to and manifestation of stress-related disorders. Such conditions are also highly sex-dependent,…$ob$, 20, false, NULL, NULL, false, 1);

  -- Section 3: Stress and Health
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Stress and Health$ob$, $ob$stress-and-health$ob$, 3, NULL);
  -- p0 [level-1 header] Stress-Related Disorders
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Stress-Related Disorders"}]}$ob$::jsonb, $ob$Stress-Related Disorders$ob$, 0, false, NULL, NULL, true, 1);
  -- p1 [text L1] While the stress response is an adaptive process that enhances our capacity to cope with challeng
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"While the stress response is an adaptive process that enhances our capacity to cope with challenging situations, excessive activation of stress systems, whether due to traumatic experiences, chronic stress, or stress activation in inappropriate contexts, can disrupt this delicate balance and lead to a cascade of negative health consequences. Since the stress response involves nearly all bodily systems, impacting not only brain function but also metabolic control, immune function, and cardiovascular function, stress-related disorders can affect both mental and physical health (De Kloet et al., 2005)."}]}$ob$::jsonb, $ob$While the stress response is an adaptive process that enhances our capacity to cope with challenging situations, excessive activation of stress systems, whether due to traumatic experiences, chronic…$ob$, 1, false, NULL, NULL, false, 1);
  -- p2 [text L1] In terms of mental health, stress exposure has been linked to a higher likelihood of developing a
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"In terms of mental health, stress exposure has been linked to a higher likelihood of developing anxiety disorders, depression, and post-traumatic stress disorder (PTSD) (Stout and Nemeroff, 1994). For example, individuals who experience chronic work stress may be more susceptible to generalized anxiety disorder or panic attacks. Those who experience a traumatic event, such as a natural disaster or an act of violence, may develop PTSD, characterized by intrusive memories, avoidance behaviors, and hyperarousal. Additionally, other psychiatric conditions, such as substance abuse, dementia, and schizophrenia, can be negatively impacted by stress (Lupien et al., 2009). Chronic stress can exacerbate symptoms of these disorders, hinder recovery, and diminish overall well-being in individuals with these conditions. For instance, stress can trigger relapses in individuals with substance abuse disorders or worsen cognitive decline in those with dementia. Importantly, many of these mental disorders occur more frequently dependent on biological sex; for depression, for example, the likelihood of developing the disorder is twice as high in women compared to men (Bangasser and Cuarenta, 2021)."}]}$ob$::jsonb, $ob$In terms of mental health, stress exposure has been linked to a higher likelihood of developing anxiety disorders, depression, and post-traumatic stress disorder (PTSD) (Stout and Nemeroff, 1994).…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Given the intricate impact of stress on multiple physiological processes, as discussed in the pre
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Given the intricate impact of stress on multiple physiological processes, as discussed in the previous sections, it is not surprising that stress exposure can have a detrimental impact on physical health. Prominent disorders induced or worsened by stress include metabolic disorders like obesity and type 2 diabetes (Kyrou et al., 2006). Stress can disrupt hormonal balance, for example, by increasing cortisol levels, which can promote fat storage and insulin resistance. Stress can also increase inflammation, a key contributor to metabolic dysfunction. Furthermore, it can promote unhealthy behaviors, such as overeating, poor sleep, and decreased physical activity, all of which contribute to metabolic disorders. Cardiovascular problems such as hypertension, coronary artery disease, and stroke are either caused or exacerbated by stress exposure (Steptoe and Kivimäki, 2012). Stress hormones can elevate heart rate and blood pressure, putting strain on the cardiovascular system. Chronic stress can also contribute to atherosclerosis, the buildup of plaque in the arteries. These cardiovascular issues often align with the impact of stress on immune function, as chronic stress can suppress the immune system, making individuals more susceptible to infections and other illnesses. For example, students experiencing academic stress may be more likely to catch a cold or flu (Cohen et al., 1991)."}]}$ob$::jsonb, $ob$Given the intricate impact of stress on multiple physiological processes, as discussed in the previous sections, it is not surprising that stress exposure can have a detrimental impact on physical…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [text L1] It is important to recognize that many of these stress-related mental and physical disorders ofte
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"It is important to recognize that many of these stress-related mental and physical disorders often co-occur, highlighting stress as a common risk factor. For instance, an individual with depression may also experience somatic symptoms like chronic pain or digestive problems (Simon et al., 1999). This underscores the interconnectedness of mind and body and the importance of a holistic approach to understanding and managing stress-related conditions. Finally, it is crucial to remember that the impact of stress on health can vary significantly depending on individual factors, such as genetic predisposition, existing health conditions, and coping mechanisms. Some individuals may be more genetically vulnerable to the effects of stress on certain systems, while others may have developed effective coping strategies that buffer against stress. These individual differences highlight the need for personalized approaches to stress management and treatment."}]}$ob$::jsonb, $ob$It is important to recognize that many of these stress-related mental and physical disorders often co-occur, highlighting stress as a common risk factor. For instance, an individual with depression…$ob$, 4, false, NULL, NULL, false, 1);
  -- p5 [level-1 header] Stress and Development
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Stress and Development"}]}$ob$::jsonb, $ob$Stress and Development$ob$, 5, false, NULL, NULL, true, 1);
  -- p6 [text L1] Individuals can be exposed to challenges at any stage throughout life. Not only the duration and 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Individuals can be exposed to challenges at any stage throughout life. Not only the duration and type of stressor, but also the timing of stress exposure, is vitally important in determining the long-term consequences (Birnie and Baram, 2025). There are specific \"sensitive windows\" during development in which the brain is particularly susceptible to changes from environmental challenges. During these times, the brain is still undergoing significant development and exhibits high plasticity. This heightened plasticity is crucial for adaptive development, allowing the brain to be shaped by experiences, but it also makes it vulnerable to disruptions. These sensitive windows can be divided into three phases: the prenatal phase, the early-life phase, and the adolescent phase. Similarly, during aging, the brain becomes increasingly susceptible to the effects of stress."}]}$ob$::jsonb, $ob$Individuals can be exposed to challenges at any stage throughout life. Not only the duration and type of stressor, but also the timing of stress exposure, is vitally important in determining the…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [text L1] Furthermore, it is suggested that specific brain regions are more or less sensitive to the effect
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Furthermore, it is suggested that specific brain regions are more or less sensitive to the effects of stress during certain periods of life, depending on their developmental stage (Lupien et al., 2009). This sensitivity corresponds to periods of rapid development in early life or periods of significant age-related changes during aging. For instance, during the prenatal phase, stress can have a programming effect on many different brain regions that contribute to HPA-axis regulation (e.g., hippocampus, prefrontal cortex, and amygdala) (Weinstock, 2008). Stress exposure in early life can particularly affect the developing hippocampus (Teicher et al., 2003), while in adolescence, the prefrontal cortex may be especially susceptible to stress (Casey et al., 2008). Conversely, during aging, the hippocampus again appears to be the region most affected by stress exposure (Lupien et al., 1998)."}]}$ob$::jsonb, $ob$Furthermore, it is suggested that specific brain regions are more or less sensitive to the effects of stress during certain periods of life, depending on their developmental stage (Lupien et al.,…$ob$, 7, false, NULL, NULL, false, 1);
  -- p8 [text L1] Interestingly, there is also evidence for the "inoculation stress hypothesis." This theory explai
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Interestingly, there is also evidence for the \"inoculation stress hypothesis.\" This theory explains how moderate, manageable exposure to stress in early life can actually prepare an individual for later life challenges (Nederhof and Schmidt, 2012). These early life experiences have \"programming\" effects on the HPA-axis and brain, and these changes can be adaptive, a concept referred to as predictive adaptive responses (PARs). Therefore, if the individual encounters a similar type of challenge in later life (a \"matched environment\"), they can utilize previously applied coping strategies and respond more effectively. However, these early life challenges may still result in maladaptation if the individual experiences an \"unmatched environment\" in later life."}]}$ob$::jsonb, $ob$Interestingly, there is also evidence for the "inoculation stress hypothesis." This theory explains how moderate, manageable exposure to stress in early life can actually prepare an individual for…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [text L1] It is important to note that especially severe or traumatic experiences early in life can have a 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"It is important to note that especially severe or traumatic experiences early in life can have a profound impact, increasing the risk of developing later psychopathologies, such as post-traumatic stress disorder (PTSD). Additionally, early life adversity is a significant risk factor for the development of major depression. These adverse outcomes underscore the importance of understanding the long-term effects of early life stress and developing effective interventions to mitigate its negative consequences."}]}$ob$::jsonb, $ob$It is important to note that especially severe or traumatic experiences early in life can have a profound impact, increasing the risk of developing later psychopathologies, such as post-traumatic…$ob$, 9, false, NULL, NULL, false, 1);
  -- p10 [level-1 header] Stress resilience
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Stress resilience"}]}$ob$::jsonb, $ob$Stress resilience$ob$, 10, false, NULL, NULL, true, 1);
  -- p11 [text L1] While early life stress can have lasting consequences, the concept of resilience highlights the 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"While early life stress can have lasting consequences, the concept of resilience highlights the potential for positive adaptation. Resilience is defined as the process of adapting well to adverse situations. Since everyone faces stress and adversity throughout life, a high level of resilience signifies optimal behavioral and physiological adaptations to these challenges, leading to greater personal well-being and success (Kalisch et al., 2024). Resilient individuals not only cope with adversity but often emerge stronger and more resourceful. They demonstrate flexibility in their responses, effectively utilizing coping mechanisms and support systems to navigate challenges. Importantly, resilience is not the same as stress resistance, which, in contrast, refers to the absence of adaptation in adverse situations."}]}$ob$::jsonb, $ob$While early life stress can have lasting consequences, the concept of resilience highlights the potential for positive adaptation. Resilience is defined as the process of adapting well to adverse…$ob$, 11, false, NULL, NULL, false, 1);
  -- p12 [text L1] A low level of resilience can lead to maladaptation and, consequently, to physical or psychologi
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"A low level of resilience can lead to maladaptation and, consequently, to physical or psychological distress (Russo et al., 2012). This might manifest as difficulty coping with stress, increased vulnerability to mental health issues, or impaired social functioning. While the mechanisms of resilience are still poorly understood, it is clear that resilience is an active and dynamic process, shaped by a complex interplay of factors. Both genetic predispositions and epigenetic modifications are known to influence individual resilience. For example, certain gene variants, such as those present in genes involved in the regulation of the HPA axis, including GR, MR or FKBP5 (van Doeselaar et al., 2025), may confer a greater capacity for emotional regulation or stress response, while epigenetic changes can alter gene expression in response to environmental influences. Disruption of this balance, through chronic stress or genetic factors, has been linked to stress related disorders, whereas restoring it promote resilience (de Kloet, 2022). Furthermore, a wide range of environmental factors can impact resilience, including the quality of social relationships, access to education and healthcare, and exposure to nurturing environments. Early-life experiences, such as secure attachment to caregivers and exposure to manageable stressors, can foster the development of resilience. Conversely, adverse childhood experiences can have a detrimental impact on resilience, increasing vulnerability to stress and mental health challenges (Nelson et al., 2025)."}]}$ob$::jsonb, $ob$A low level of resilience can lead to maladaptation and, consequently, to physical or psychological distress (Russo et al., 2012). This might manifest as difficulty coping with stress, increased…$ob$, 12, false, NULL, NULL, false, 1);

  -- Section 4: Stress Management and Interventions
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Stress Management and Interventions$ob$, $ob$stress-management-and-interventions$ob$, 4, NULL);
  -- p0 [text L0] Stress management interventions aim to mitigate the physiological, psychological, and behavioral 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Stress management interventions aim to mitigate the physiological, psychological, and behavioral impacts of stress. Their goal is not to eliminate stress responsiveness, which is often adaptive, but to reduce excessive or persistent stress, facilitate recovery from stressful situations, as well as prevent or treat the adverse consequences of stress. There is an increasing number of interventions that can act at complementary levels, including mesures directed at the stressor itself, behavioral and psychological approaches and, when clinically indicated, pharmacological treatments (Lehrer and Woolfolk, 2021; World Health Organization, 2022)."}]}$ob$::jsonb, $ob$Stress management interventions aim to mitigate the physiological, psychological, and behavioral impacts of stress. Their goal is not to eliminate stress responsiveness, which is often adaptive, but…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [level-1 header] Behavioral and psychological interventions
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Behavioral and psychological interventions"}]}$ob$::jsonb, $ob$Behavioral and psychological interventions$ob$, 1, false, NULL, NULL, true, 1);
  -- p2 [text L1] Behavioral and psychological interventions primarily target individual responses to stress, aimin
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Behavioral and psychological interventions primarily target individual responses to stress, aiming to improve coping strategies and emotional regulation. However, whenever the source of stress can be modified, interventions directed to reduce excessive demands, increasing predictability or control, strengthening social support, or modifying adverse environmental or organizational conditions should also be considered, where feasible. Accordingly, individual stress-management strategies should be considered as one component of a broader approach to stress reduction (World Health Organization, 2022). They include several categories:"}]}$ob$::jsonb, $ob$Behavioral and psychological interventions primarily target individual responses to stress, aiming to improve coping strategies and emotional regulation. However, whenever the source of stress can…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [list L1] Cognitive behavioral therapy (CBT) is a structured, relatively brief psychotherapy aimed at ident
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Cognitive behavioral therapy (CBT)</strong> is a structured, relatively brief psychotherapy aimed at identifying and modifying unhelpful patterns of cognition and behavior and developing more effective coping and problem-solving strategies to reduce emotional distress. It operates on the premise that cognitive processes influence emotional responses and behaviors, and it uses techniques such as cognitive reappraisal, behavioral activation, exposure and problem solving, with the goal of restructuring maladaptive thought patterns and behaviors and to develop healthier coping mechanisms. CBT has shown significant effectiveness in reducing stress and stress-related disorders across anxiety and depressive disorders and other stress-related psychological difficulties (Carpenter et al., 2018). Today, it is considered an evidence-based approach for managing stress. Recent advancements in technology have facilitated the delivery of CBT through digital platforms, and internet-delivered CBT has been shown to be as effective as face-to-face therapy in reducing stress and anxiety symptoms (Heber et al., 2017; Carlbring et al., 2018)."]}]}$ob$::jsonb, $ob$Cognitive behavioral therapy (CBT) is a structured, relatively brief psychotherapy aimed at identifying and modifying unhelpful patterns of cognition and behavior and developing more effective…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [list L1] Mindfulness-based interventions (MBIs) are structured approaches aimed at developing present-mome
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Mindfulness-based interventions (MBIs)</strong> are structured approaches aimed at developing present-moment awareness and less judgmental acceptance and reactive relationship to thoughts, emotions and bodily sensations. Among the best studied are mindfulness-based stress reduction (MBSR) and mindfulness-based cognitive therapy (MBCT). Recent meta-analyses have indicated small-to-moderate benefits for anxiety, depressive symptoms and psychological distress, although their effectiveness is generally lower when the comparison manipulation is active instead of a passive control condition (Goyal et al., 2014; Goldberg et al., 2022). Their effectiveness has been attributed to enhanced emotional and attentional regulation, improvements in cognitive flexibility, and reductions in rumination."]}]}$ob$::jsonb, $ob$Mindfulness-based interventions (MBIs) are structured approaches aimed at developing present-moment awareness and less judgmental acceptance and reactive relationship to thoughts, emotions and…$ob$, 4, false, NULL, NULL, false, 1);
  -- p5 [list L1] Relaxation techniques are also behavioral strategies aimed at reducing subjective tension and phy
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Relaxation techniques</strong> are also behavioral strategies aimed at reducing subjective tension and physiological arousal and facilitating recovery from stress f(Manzoni et al., 2008; Lehrer and Woolfolk, 2021). Common approaches include: i) progressive muscle relaxation, which involves systematically tensing and relaxing different muscle groups; ii) autogenic training, which uses internally focused verbal exercises involving bodily sensations such as warmth and heaviness; and iii) deep breathing exercises, such as diaphragmatic breathing, which involve slow, deep breaths to regulate physiological arousal. Relaxation training has been shown to have beneficial effects on anxiety and perceived stress, although its effectiveness varies with specific techniques and populations (Manzoni et al., 2008)."]}]}$ob$::jsonb, $ob$Relaxation techniques are also behavioral strategies aimed at reducing subjective tension and physiological arousal and facilitating recovery from stress f(Manzoni et al., 2008; Lehrer and Woolfolk,…$ob$, 5, false, NULL, NULL, false, 1);
  -- p6 [list L1] Mind-body practices are holistic approaches that address the interconnectedness of physical and m
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Mind-body practices</strong> are holistic approaches that address the interconnectedness of physical and mental health by integrating physical movement, breath control, attention, and mental focus. Among the most prominent are yoga, tai chi, and qigong. Yoga, in particular, has been associated with reductions in cortisol and autonomic measures, although physiological findings vary considerably among studies (Pascoe et al., 2017; Cramer et al., 2018). Although some emerging evidence indicates changes in brain structure and function following these practices, the robustness of this evidence is considerably less established than the evidence of their effects on subjective psychological outcomes."]}]}$ob$::jsonb, $ob$Mind-body practices are holistic approaches that address the interconnectedness of physical and mental health by integrating physical movement, breath control, attention, and mental focus. Among the…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [list L1] Physical activity and exercise, when performed regularly, are well-established means to mitigate 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Physical activity and exercise</strong>, when performed regularly, are well-established means to mitigate stress and improve physical and mental health, including reductions in symptoms of depression, anxiety and psychological distress (Singh et al., 2023; Noetel et al., 2024). Benefits of regular exercise (e.g., walking, jogging, strength training) arise through multiple interacting biological and psychological mechanisms, including changes in neuroendocrine regulation, neuroplasticity, sleep and psychological processes. Several studies have shown that various forms of exercise can be as effective as traditional treatments for anxiety and depression, and can also complement established treatments."]}]}$ob$::jsonb, $ob$Physical activity and exercise, when performed regularly, are well-established means to mitigate stress and improve physical and mental health, including reductions in symptoms of depression,…$ob$, 7, false, NULL, NULL, false, 1);
  -- p8 [text L1] Finally, adequate sleep and opportunities for recovery are also important components of stress ma
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Finally, adequate sleep and opportunities for recovery are also important components of stress management. When persistent insomnia develops, cognitive behavioral therapy for insomnia (CBT-I) is an evidence-based first-line treatment that produces robust improvements in sleep outcomes (Trauer et al., 2015; Riemann et al., 2023)."}]}$ob$::jsonb, $ob$Finally, adequate sleep and opportunities for recovery are also important components of stress management. When persistent insomnia develops, cognitive behavioral therapy for insomnia (CBT-I) is an…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [level-1 header] Pharmacological interventions
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Pharmacological interventions"}]}$ob$::jsonb, $ob$Pharmacological interventions$ob$, 9, false, NULL, NULL, true, 1);
  -- p10 [text L1] Pharmacological interventions used in stress management are medications generally used to treat 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Pharmacological interventions used in stress management are medications generally used to treat particular symptoms or diagnosed stress-related conditions, such as anxiety disorders, depression or PTSD. Although emerging evidence indicates that the mechanisms of action may be broader than currently understood, most of the current treatments are traditionally believed to act on neurotransmitter systems involved in arousal, anxiety and mood regulation. Thus, they do not primarily target the HPA axis, and their specific selection depends on the characteristics of the symptoms and on the disorder being treated."}]}$ob$::jsonb, $ob$Pharmacological interventions used in stress management are medications generally used to treat particular symptoms or diagnosed stress-related conditions, such as anxiety disorders, depression or…$ob$, 10, false, NULL, NULL, false, 1);
  -- p11 [list L1] Beta-adrenergic blockers, commonly known as beta-blockers, mitigate the physiological effects of
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Beta-adrenergic blockers</strong>, commonly known as beta-blockers, mitigate the physiological effects of sympathetic activation by antagonizing β-adrenergic receptors and thereby limiting the actions of adrenaline and noradrenaline on peripheral target organs. Propranolol, for example, blocks β1- (reducing catecholamine-induced increases in heart rate and cardiac contractility) and β2- (reducing manifestations such as tremor) adrenergic receptors. Their effects, therefore, include rapiod reductions of the physical manifestations of stress-related adrenergic arousal, such as palpitations, without affecting cognitive and emotional processing. Thus, they may be particularly useful in individuals and conditions in which these peripheral symptoms are particularly exacerbated, such as performance anxiety, but existing evidence does not support their effectiveness as a routine approach to treat anxiety disorders of stress (Steenen et al., 2016)."]}]}$ob$::jsonb, $ob$Beta-adrenergic blockers, commonly known as beta-blockers, mitigate the physiological effects of sympathetic activation by antagonizing β-adrenergic receptors and thereby limiting the actions of…$ob$, 11, false, NULL, NULL, false, 1);
  -- p12 [list L1] Anxiolytics, such as benzodiazepines (e.g., diazepam, lorazepam), enhance the effect of the majo
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Anxiolytics</strong>, such as <strong>benzodiazepines</strong> (e.g., diazepam, lorazepam), enhance the effect of the major inhibitory neurotransmitter GABA by acting as positive allosterid modulators of GABA-A receptors.Their binding enhances the effects of GABA, strengthening inhibitory transmission and rapidly reducing neuronal excitability across brain circuits involved in arousal and anxiety, along with sedative and anxiolytic effects. Although they show effectiveness for short-term anxiolytic relief, benzodiazepines can also impair memory, alertness and psychomotor performance which, along with their strong potential for the development of tolerance, physiological dependence and withdrawal with repeated use illustrates the need for careful monitoring and the importance of new research directed to the development of novel treatments. In fact, current benzodiazepines are generally useful for short-term relief of severe acute anxiety, but not appropriate for the long-term treatment of anxiety disorders (Lader, 2011; National Institute for Health and Care Excellence, 2011). <strong>Other anxiolytic drugs</strong> act through different mechanisms. In particular, <strong>pregabalin</strong>, used in generalized anxiety disorder (GAD), acts through the binding to voltage-gated calcium channels in the central nervous system, decreasing excitatory signaling. Although the precise mechanism of action involved in its anxiolytic effects are not fully understood, several clinical trials support its effectiveness in GAD, and current guidelines consider pregabalin an alternative when other treatments are not well tolerated (Pande et al., 2003; National Institute for Health and Care Excellence, 2011)."]}]}$ob$::jsonb, $ob$Anxiolytics, such as benzodiazepines (e.g., diazepam, lorazepam), enhance the effect of the major inhibitory neurotransmitter GABA by acting as positive allosterid modulators of GABA-A…$ob$, 12, false, NULL, NULL, false, 1);
  -- p13 [list L1] Antidepressants, particularly selective serotonin reuptake inhibitors (SSRIs) and serotonin-nore
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"list","ordered":false,"items":["<strong>Antidepressants</strong>, particularly selective serotonin reuptake inhibitors (SSRIs) and serotonin-norepinephrine reuptake inhibitors (SNRIs), are widely used for longer-term treatment of depression and anxiety disorders. SSRIs inhibit the serotonin transporter (SERT), reducing presynaptic reuptake of serotonin and, thus, increasing serotonergic signaling. SNRIs additionally inhibit the norepinephrine transporter (NET) and, thus, increase both serotonergic and noradrenergic transmission. For example, sertraline primarily inhibits serotonin reuptake. Importantly, the impact of these antidepressants on the inhibition of neurotransmitter transporters takes place much earlier than their therapeutic effectiveness, which emerges over subsequent weeks, questioning the actual involvement of monoamine mechanisms in the therapeutic mechanisms of action of these drugs. In fact, evidence has accumulated that, instead of resulting simply from their immediate effects on monoamine concentrations, the therapeutic actions of antidepressants involve progressive adaptations in receptor signaling and synaptic and network plasticity (Meyer et al., 2004; Castren, 2013; Brunello et al., 2024)."]}]}$ob$::jsonb, $ob$Antidepressants, particularly selective serotonin reuptake inhibitors (SSRIs) and serotonin-norepinephrine reuptake inhibitors (SNRIs), are widely used for longer-term treatment of depression and…$ob$, 13, false, NULL, NULL, false, 1);
  -- p14 [text L1] Although pharmacological treatments can alleviate the physiological and psychological symptoms o
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Although pharmacological treatments can alleviate the physiological and psychological symptoms of stress and stress-related disorders, they are particularly effective when combined with behavioral and psychological interventions. Moving forward, multimodal approaches tailored to individual needs and contexts hold promise for achieving sustained stress reduction and resilience."}]}$ob$::jsonb, $ob$Although pharmacological treatments can alleviate the physiological and psychological symptoms of stress and stress-related disorders, they are particularly effective when combined with behavioral…$ob$, 14, false, NULL, NULL, false, 1);

  -- Section 5: Conclusion
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Conclusion$ob$, $ob$conclusion$ob$, 5, NULL);
  -- p0 [text L0] In conclusion, this chapter has navigated the intricate landscape of stress, underscoring its fun
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"In conclusion, this chapter has navigated the intricate landscape of stress, underscoring its fundamental nature as a biological response essential for survival, yet capable of profound detriment when dysregulated. We have traced its conceptual evolution from early theories of homeostasis to the contemporary understanding of allostasis, allostatic load, and the brain's central role. The detailed interplay of brain circuits and physiological response systems, such as the SNS and HPA axis, affects virtually every physiological process and brain region, ultimately leading to an adaptation to the stressful situation. Crucially, we have seen that the impact of stress is highly dependent on its duration and context; acute stress can be adaptive, enhancing functions like memory consolidation, while chronic stress frequently leads to maladaptive structural and functional changes in the brain, impairing cognition, altering behavior, and significantly increasing the risk for a spectrum of physical and mental health disorders. The profound influence of sex differences and the timing of stress exposure across sensitive developmental periods particularly highlight the personalized nature of stress vulnerability and resilience."}]}$ob$::jsonb, $ob$In conclusion, this chapter has navigated the intricate landscape of stress, underscoring its fundamental nature as a biological response essential for survival, yet capable of profound detriment…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [text L0] Emerging research continues to delve deeper into the molecular and cellular mechanisms underlying
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Emerging research continues to delve deeper into the molecular and cellular mechanisms underlying stress-induced plasticity, the neurobiology of resilience, and the distinct stress processing pathways and outcomes observed between sexes. There is a growing focus on identifying reliable biomarkers and underlying mechanisms for stress vulnerability and treatment response, the long-term epigenetic consequences of developmental stress exposure, and the potential for interventions to reverse or mitigate stress-induced neuropathology. Further exploration of the interplay between genetic predispositions and environmental factors, including the promising \"stress inoculation\" hypothesis, will be vital for understanding individual differences."}]}$ob$::jsonb, $ob$Emerging research continues to delve deeper into the molecular and cellular mechanisms underlying stress-induced plasticity, the neurobiology of resilience, and the distinct stress processing…$ob$, 1, false, NULL, NULL, false, 0);
  -- p2 [text L0] The societal implications of this research are vast. A comprehensive understanding of stress prov
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The societal implications of this research are vast. A comprehensive understanding of stress provides a critical framework for public health initiatives aimed at preventing stress-related illnesses, which impose a considerable burden on healthcare systems and economic productivity. This knowledge informs the development of targeted interventions, ranging from cognitive behavioral therapies and mindfulness practices to pharmacological treatments and lifestyle adjustments like physical exercise. It also critically underscores the importance of creating supportive environments in workplaces, schools, and communities. Ultimately, continued research into the multifaceted nature of stress holds the key to fostering individual and societal resilience, improving mental and physical well-being, and mitigating the pervasive impact of stress in an increasingly demanding world."}]}$ob$::jsonb, $ob$The societal implications of this research are vast. A comprehensive understanding of stress provides a critical framework for public health initiatives aimed at preventing stress-related illnesses,…$ob$, 2, false, NULL, NULL, false, 0);

  -- Section 6: Box 1: Bruce S. McEwen
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Box 1: Bruce S. McEwen$ob$, $ob$box-1-bruce-s-mcewen$ob$, 6, NULL);
  -- p0 [text L0] Bruce S. McEwen (1938–2020) fundamentally reshaped modern neuroscience by recasting the brain as 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Bruce S. McEwen (1938–2020) fundamentally reshaped modern neuroscience by recasting the brain as the central regulating organ of stress adaptation rather than a passive target of physiological strain. Moving beyond classical models of homeostasis that emphasized maintaining fixed internal baselines, McEwen applied the concept of allostasis—achieving stability through dynamic physiological adaptation—to neuroendocrinology. In this framework, primary mediators such as glucocorticoids, catecholamines, and pro-inflammatory cytokines actively adjust systemic function to meet environmental demands. However, when these protective mechanisms are chronically engaged, fail to habituate, or prove slow to shut off, they inflict cumulative biological wear and tear. In 1993, McEwen and Eliot Stellar conceptualized this cost as allostatic load, which progresses to allostatic overload when environmental demands persistently exceed an organism's adaptive capacity (McEwen and Stellar, 1993)."}]}$ob$::jsonb, $ob$Bruce S. McEwen (1938–2020) fundamentally reshaped modern neuroscience by recasting the brain as the central regulating organ of stress adaptation rather than a passive target of physiological…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [text L0] Crucially, McEwen’s research demonstrated that chronic stress induces region-specific, structural
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Crucially, McEwen’s research demonstrated that chronic stress induces region-specific, structural neuroplastic remodeling rather than static cell loss. Prolonged exposure to elevated stress hormones drives dendritic atrophy and synaptic spine loss in the hippocampus and prefrontal cortex—impairing declarative memory, context processing, and top-down executive control (McEwen, 2007; McEwen and Morrison, 2013). Conversely, chronic stress promotes dendritic growth and hyper-connectivity in the basolateral amygdala, amplifying fear processing and emotional reactivity. This shift shifts neural network dynamics toward heightened anxiety and blunted cognitive regulation. Because these structural alterations represent adaptive neuroplasticity rather than permanent degeneration, McEwen emphasized that stress-induced brain changes remain fundamentally malleable and amenable to behavioral, cognitive, and pharmacological interventions (McEwen and Akil, 2020)."}]}$ob$::jsonb, $ob$Crucially, McEwen’s research demonstrated that chronic stress induces region-specific, structural neuroplastic remodeling rather than static cell loss. Prolonged exposure to elevated stress hormones…$ob$, 1, false, NULL, NULL, false, 0);

  -- Section 7: Box 2: The match-mismatch hypothesis
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Box 2: The match-mismatch hypothesis$ob$, $ob$box-2-the-match-mismatch-hypothesis$ob$, 7, NULL);
  -- p0 [text L0] The match-mismatch hypothesis (or stress inoculation hypothesis) proposes that early-life experie
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The match-mismatch hypothesis (or stress inoculation hypothesis) proposes that early-life experience does not simply cause vulnerability; rather, it programs and adapts the central nervous system and stress systems for a specific future environment. According to this theory, psychiatric risk or resilience depends on the degree to which an adult’s environment matches their early developmental programming. There is growing evidence for this evolutionary and developmental concept, explaining how mild to moderate, manageable exposure to stress in early life can actually prepare an individual for challenges encountered later in life (Nederhof and Schmidt, 2012). During critical sensitive periods of development, these early experiences exert profound programming effects on the central nervous system and, rather than causing irreversible damage, these neurobiological changes can be adaptive, reflecting a biological mechanism known as predictive adaptive responses (Gluckman and Hanson, 2004). Through this predictive lens, the developing organism uses early environmental signals to forecast the nature of its future environment and recalibrates its stress-response machinery accordingly. Consequently, if an individual encounters a similar environment in adulthood - a matched environment - they can rely on previously established neurobehavioral adaptations to cope more effectively. However, if the adult environment turns out to be vastly different from what was predicted during development, be it more or less stressful, these early adaptations may result in maladaptation and heightened psychiatric risk."}]}$ob$::jsonb, $ob$The match-mismatch hypothesis (or stress inoculation hypothesis) proposes that early-life experience does not simply cause vulnerability; rather, it programs and adapts the central nervous system…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [text L0] Empirical support for the match-mismatch match-mismatch hypothesis has been provided from animal 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Empirical support for the match-mismatch match-mismatch hypothesis has been provided from animal studies. In a rodent study, mice subjected to either early life or adult stress paradigms (mismatched environments) displayed alterations in anxiety and social behavior, which were not found when stress in early life and adulthood was combined (matched environments) (Santarelli et al., 2017). Similar findings emerge from non-human primate studies in squirrel monkeys, showing that stress inoculation can enhance adult arousal regulation and resilience (Lyons et al., 2009). Human psychological and clinical research increasingly aligns with these basic neuroscience findings. Within developmental psychology, the \"Hidden Talents\" framework demonstrates that individuals raised in harsh, unpredictable human environments often perform poorly on standard psychometric tests, which are typically designed for quiet, low-threat environments representing a structural mismatch (Ellis et al., 2022; Porter and Handley, 2026). However, when evaluated under conditions involving high uncertainty, acute pressure, or rapid environmental shifts, these individuals exhibit superior capabilities in threat detection, mental flexibility, and rapid task-switching compared to peers from affluent, low-stress backgrounds (Seery et al., 2010)."}]}$ob$::jsonb, $ob$Empirical support for the match-mismatch match-mismatch hypothesis has been provided from animal studies. In a rodent study, mice subjected to either early life or adult stress paradigms (mismatched…$ob$, 1, false, NULL, NULL, false, 0);

